/* Meinen Typ finden: Nachschlagen. Suche und Rubriken zu Typ-Eigenschaften (Ich-Sätze), Sammeln und Auswerten. Inhalte aus dem Repertorium von Neun Seelenblüten, ohne Blüten und ohne Subtypen. */
const REP = {"typ":{"1":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich schlucke meinen Zorn hinunter.","I swallow my anger.",3],["Ich sorge für Ordnung, weil ich keinen inneren Frieden finde.","I create order because I cannot find inner peace.",3],["Ich erlebe mein Leben nicht, ich regle es.","I don't experience my life, I regulate it.",3],["Unter meinem Pflichtbewusstsein spüre ich einen Druck, der ungelöst bleibt.","Beneath my sense of duty I feel a pressure that stays unresolved.",3],["Ich empfinde feine, nie ausgesprochene Empörung über das Unvollkommene.","I feel a fine, never voiced indignation at the imperfect.",3],["Ich verwandle meinen Antrieb in Tugend.","I turn my drive into virtue.",3],["Mein innerer Richter hat das Kommando übernommen.","My inner judge has taken over.",3],["Meine Reinheit ist gefroren und zu Härte geworden.","My purity has frozen into hardness.",3],["Mein Gewissen steht an der Stelle meines Selbstgefühls.","My conscience stands in the place of my self-feeling.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich möchte gelassen sein statt streng.","I want to be serene instead of severe.",3],["Ich spüre, dass meine Reinheit Bewegung braucht.","I sense that my purity needs movement.",3],["Ich möchte Ordnung entdecken, nicht erschaffen müssen.","I want to discover order rather than have to create it.",3],["Ich möchte vom Richter zum weisen Beobachter werden.","I want to go from being a judge to being a wise observer.",2],["Mein Gewissen soll mir dienen, nicht über mich herrschen.","My conscience should serve me, not rule me.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Wenn ich richtig handle, bin ich sicher.“","“If I act rightly, I am safe.”",3],["„Ich bin sicher, wenn ich kontrolliert bin.“","“I am safe when I am in control.”",3],["„Wenn ich wild bin, verliere ich Nähe. Wenn ich brav bin, werde ich gesehen.“","“If I am wild I lose closeness. If I am good I am seen.”",3],["„Nur wenn ich fehlerfrei bin, bin ich liebenswert.“","“Only if I am flawless am I lovable.”",3],["Ich erlebe Liebe als an Bedingungen geknüpft: Sei brav, ordentlich, zuverlässig.","I experience love as conditional: be good, orderly, reliable.",3],["„Ich möchte ruhig werden, aber ich kann nicht aufhören zu kontrollieren.“","“I want to become calm but I cannot stop controlling.”",3],["Ich empfinde Entspannung als moralische Schwäche.","I see relaxing as moral weakness.",3],["Ich erlaube mir Ruhe erst, wenn alles perfekt ist.","I only allow myself rest when everything is perfect.",3],["Ein Fehler fühlt sich für mich wie Versagen an.","A mistake feels like failure to me.",3],["Ich empfinde das Leben selbst als unrein.","I find life itself impure.",2]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["„Ich bin nicht wütend, ich korrigiere dich nur zu deinem Besten.“","“I am not angry, I am only correcting you for your own good.”",2],["Ich behalte mein Ideal, ohne zu verhärten (Ordnung ohne Härte).","I keep my ideal without hardening (order without hardness).",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit und Urteil","e":"Attention and judgement","x":[["Ich sehe sofort, was fehlt, nicht was da ist.","I see at once what is missing, not what is there.",3],["Ich habe ein seelisches Radar für das Nicht-Perfekte.","I have a soul radar for the imperfect.",3],["Ich erkenne Fehler auf den ersten Blick.","I spot mistakes at first glance.",3],["Ich sehe, wie alles noch besser sein könnte.","I see how everything could be even better.",3],["Ich prüfe alles nach, mein Gewissen ist überempfindlich.","I check everything again, my conscience is oversensitive.",3],["Ich beurteile andere so streng wie mich selbst.","I judge others as strictly as myself.",3],["Meine Liebe zum Wahren wird unbewusst zum Kampf gegen das Falsche.","My love of truth turns unconsciously into a fight against the false.",3],["Mein Denken (Prinzip) und mein Handeln (Pflicht) sind verhärtet.","My thinking (principle) and my acting (duty) have hardened.",2],["Ich suche exaktes, faktentreues, ethisch korrektes Wissen.","I look for exact, factual, ethically correct knowledge.",2],["Ich lerne systematisch und gründlich.","I learn systematically and thoroughly.",2]]},{"i":"idealist","d":"Ideale und Werte","e":"Ideals and values","x":[["Ich bin idealistisch und liebe die Wahrheit.","I am idealistic and love the truth.",3],["Ich will, dass die Dinge stimmen, bis ins Innere.","I want things to be right, right through to the core.",3],["Ich will der Welt ein Beispiel geben.","I want to set an example for the world.",3],["Ich bleibe meinen Prinzipien treu und achte auf Details.","I stay loyal to my principles and pay attention to detail.",2],["Ich setze mich unermüdlich für das Richtige ein.","I commit myself tirelessly to what is right.",2]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich spüre eine leise, stetige innere Anspannung.","I feel a quiet, steady inner tension.",3],["Ich habe das Gefühl, nie ganz fertig und nie ganz richtig zu sein.","I feel I am never quite finished or quite right.",3],["Selbst Lob beruhigt mich nicht.","Even praise does not calm me.",3],["Ich finde keine wirkliche Entlastung, nur kurze Momente der Korrektheit.","I find no real relief, only brief moments of correctness.",3],["Ich bin innerlich unruhig.","I am restless inside.",3],["Ich habe die Freude verloren: Ich tue, was ich soll, und fühle kaum noch, warum.","I have lost my joy: I do what I should and hardly feel why.",3],["Ich bin chronisch erschöpft von meinem eigenen Anspruch.","I am chronically exhausted by my own standards.",3],["Ich sehne mich nach Entlastung und habe zugleich Angst vor Entspannung.","I long for relief and at the same time fear relaxing.",3],["Ich habe früh Unsicherheit im emotionalen Raum erlebt.","I experienced insecurity in the emotional space early on.",2],["Ich habe das Gefühl, mich strafen zu müssen, auch wenn keine Schuld besteht.","I feel I have to punish myself even when there is no guilt.",2]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich halte meinen Zorn zurück und verwandle ihn in Selbstdisziplin.","I hold back my anger and turn it into self-discipline.",3],["Mein Zorn richtet sich nach innen und wird zu Spannung.","My anger turns inward and becomes tension.",3],["Ich werde gereizt, wenn Dinge meinen hohen Ansprüchen nicht entsprechen.","I get irritated when things do not meet my high standards.",3],["Mein Zorn zeigt sich als gereizte, angespannte Energie.","My anger shows as irritated, tense energy.",2],["Ich verstecke meinen Zorn und bleibe nett.","I hide my anger and stay nice.",3],["Zorn, Lust, Bedürftigkeit und Spontaneität verwandle ich in moralische Energie.","I turn anger, desire, neediness and spontaneity into moral energy.",3],["Bei Fehlern bestrafe ich mich selbst.","When I make mistakes, I punish myself.",3]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich plane sorgfältig, handle präzise und kontrolliere meine Impulse.","I plan carefully, act precisely and control my impulses.",3],["Ich halte mich an alle Regeln des guten Benehmens.","I follow all the rules of good manners.",3],["Ich brauche strukturierte Routinen und klare Regeln.","I rely on structured routines and clear rules.",2],["Ich überprüfe meine Arbeit kritisch, um Fehler zu vermeiden.","I check my work critically to avoid mistakes.",3],["Ich halte meine Gefühle, meinen Körper, sogar den Kontakt zurück, statt mich auszudrücken.","I hold back my feelings, my body, even contact, rather than expressing myself.",3],["Ich diszipliniere mich, um ein Beispiel zu geben.","I discipline myself to set an example.",3],["Ich versage mir Freuden.","I deny myself pleasures.",3],["Ich habe Spaß an Puzzles, handwerklichen Projekten, Gartenarbeit und Renovieren.","I enjoy puzzles, craft projects, gardening and renovating.",1],["Tugendhaft zu sein ist zu meiner Identität geworden.","Being virtuous has become my identity.",3]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich liebe durch Ehrlichkeit, Integrität und gegenseitige Verbesserung.","I love through honesty, integrity and mutual improvement.",2],["Ich bin liebevoll, aber anspruchsvoll.","I am loving but demanding.",2],["Ich will meinen Partner „zu seinem Besten“ korrigieren.","I want to correct my partner “for their own good”.",2],["Ich halte andere an meinem eigenen Maßstab fest.","I hold others to my own standard.",3],["Ich habe Reformeifer und versuche, mein Umfeld moralisch zu erziehen.","I have reforming zeal and try to educate my surroundings morally.",2],["Nach außen wirke ich ruhig, aber es kostet mich viel Mühe.","I seem calm on the outside, but it takes a lot of effort.",3]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich habe Macht durch moralische Autorität und Kompetenz.","I have power through moral authority and competence.",2],["Man hält mich für integer und verlässlich.","People see me as having integrity and being reliable.",2],["Meine Stärken sind Integrität, Verantwortungsbewusstsein und Ethik.","My strengths are integrity, a sense of responsibility and ethics.",2],["Meine Schwächen sind übermäßiger Perfektionismus und Strenge gegen mich und andere.","My weaknesses are excessive perfectionism and strictness toward myself and others.",2],["Ich strebe nach Perfektion und Exzellenz.","I strive for perfection and excellence.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck und Spannung","e":"Reaction to pressure and tension","x":[["Mein vegetatives Nervensystem steht unter Daueranspannung.","My autonomic nervous system is under constant tension.",2],["Ich erlebe Entspannung als Gefahr.","I experience relaxation as danger.",3],["Mein Gewissen wirkt wie ein Richter, der bestraft.","My conscience works like a judge who punishes.",3],["Mein Anspruch steigt weiter, wenn eine Aufgabe erledigt ist.","My demands rise again once a task is done.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich verkehre Aggression in Moral (Reaktionsbildung).","I turn aggression into morality (reaction formation).",3],["Ich presse meine Lebenskraft durch das Sieb der Moral (Sublimierung).","I press my life force through the sieve of morality (sublimation).",3],["Ich verdränge meine Triebe, und mein Ich vermittelt erschöpft.","I repress my drives, and my ego mediates in exhaustion.",3],["Meine Spontaneität bleibt im Schatten.","My spontaneity stays in the shadow.",3],["Ich will das Höhere erzwingen, indem ich das Menschliche meide (Askese).","I try to force the higher by avoiding the human (asceticism).",2],["Ich setze Kontrolle an die Stelle von Vertrauen.","I use control in place of trust.",3]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich wurde früh kritisiert und beurteilt.","I was criticised and judged early on.",3],["Kritik und Urteil haben mich früh tief verletzt.","Criticism and judgement hurt me deeply early on.",3],["Ich habe die Maßstäbe der anderen verinnerlicht.","I internalised the standards of others.",3],["Ich überwache mich selbst, um dem Schmerz des Beurteiltwerdens zuvorzukommen.","I monitor myself to forestall the pain of being judged.",3],["Ursprünglich war ich spontan, unbeschwert, neugierig und gelassen.","Originally I was spontaneous, carefree, curious and relaxed.",2],["Mein Spontanes wurde gebremst, mein Wildes gezähmt.","My spontaneity was braked, my wildness tamed.",3],["Mein Zorn wurde früh als gefährlich oder unanständig etikettiert.","My anger was labelled early on as dangerous or improper.",3],["Sicherheit fand ich dort, wo Regeln galten.","I found safety where rules applied.",3]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Meine Nackenmuskeln sind stark verspannt.","The muscles in my neck are very tense.",3],["Ich halte meinen Brustkorb fest.","I hold my chest tight.",3],["Ich atme flach.","I breathe shallowly.",3],["Mein Körper ist zum moralischen Instrument geworden, ein Panzer aus Haltung.","My body has become a moral instrument, an armour of posture.",3],["Ich halte mich gerade, kleide mich sorgfältig und kontrolliere meine Stimme.","I stand upright, dress carefully and control my voice.",3],["Mein Blick ist wach, aber selten weich.","My gaze is alert but rarely soft.",3],["Ich spüre Enge im Zwerchfell.","I feel tightness in my diaphragm.",2],["Mein Zorn zeigt sich in meiner Haltung, meinem Tonfall und der Präzision meiner Sprache.","My anger shows in my posture, my tone and the precision of my speech.",3],["Ich wünsche mir einen entspannten Kiefer und einen ruhigen Atem.","I long for a relaxed jaw and a calm breath.",1]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["„Man muss …“","“One must …”",3],["„Ich darf nicht …“","“I must not …”",3],["„Es gehört sich, dass …“","“It is proper that …”",3],["„Ich sollte …“","“I should …”",3],["Ich spreche exakt und präzise.","I speak exactly and precisely.",3],["„Ich bin zum ersten Mal nicht nur richtig, sondern echt.“","“For the first time I am not just right but real.”",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich möchte gelassen sein: nichts festhalten, nichts erzwingen.","I want to be serene: hold nothing, force nothing.",3],["Ich möchte vertrauen, ohne meine Wachheit zu verlieren.","I want to trust without losing my alertness.",3],["Ich möchte Integrität aus Bewusstheit leben statt aus Kontrolle.","I want to live integrity from awareness instead of from control.",3],["Ich möchte, dass aus Selbstdisziplin Achtsamkeit wird und aus moralischer Härte Klarheit.","I want self-discipline to turn into mindfulness and moral hardness into clarity.",3],["Ich wünsche mir Frieden ohne Bedingung.","I long for peace without condition.",3],["Ich möchte, dass mein Zorn zu Wärme, Schaffenskraft und ruhiger Präsenz wird.","I want my anger to become warmth, creative power and calm presence.",3],["Ich möchte dem Leben zustimmen, statt es zu korrigieren.","I want to affirm life instead of correcting it.",3],["Ich möchte, dass mein Anspruch organisch wird, eine innere Ordnung, die sich selbst trägt.","I want my standard to become organic, an inner order that sustains itself.",2],["Ich möchte nicht mehr „richtig“, sondern „wahr“ sein.","I want to be “true” rather than “right”.",3],["Ich möchte, dass aus Recht Güte wird und aus Strenge Würde.","I want law to become kindness and strictness to become dignity.",2],["Ich möchte Ideal, Gewissen und Herz verbinden und Vorbild sein, ohne zu richten.","I want to connect ideal, conscience and heart, and be a model without judging.",2],["Ich möchte präsent sein, ohne sofort zu bewerten.","I want to be present without immediately evaluating.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich bemerke erste Zeichen im Körper: tieferen Atem, wärmere Stimme, weichere Schultern.","I notice first signs in my body: deeper breath, a warmer voice, softer shoulders.",2],["Ich kann zwiespältig sein: Ich fühle, ich verliere meinen Anspruch, obwohl nur der Zwang geht.","I can feel ambivalent: I feel I am losing my standard, though only the compulsion goes.",2],["Ich erlaube mir Zeit für Pausen ohne Leistung.","I allow myself time for pauses without achievement.",1],["Ich möchte ruhig sein, ohne etwas zu leisten.","I want to be still without achieving anything.",2]]}]}],"2":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich bin stolz darauf, so fürsorglich zu sein, und fühle mich dadurch ein wenig über anderen.","I am proud of how caring I am, and it makes me feel a little above others.",3],["Ich erlebe Liebe als etwas, das ich leisten muss.","I experience love as something I have to achieve.",3],["Mein Selbstwert liegt in dem, was ich tue, nicht in dem, was ich bin.","My self-worth lies in what I do, not in who I am.",3],["Fehlende Liebe erlebe ich als Aufgabe, die ich lösen muss.","I experience missing love as a task I have to solve.",3],["Ich gebe, statt zu fühlen, und sorge mich, statt in Kontakt zu sein.","I give instead of feeling, and I care instead of connecting.",3],["Mein Leben dreht sich um Beziehungen.","My life revolves around relationships.",3],["Gebraucht zu werden gibt mir das Gefühl, dass ich existieren darf.","Being needed gives me the feeling that I am allowed to exist.",3],["Ich kenne mich mit dem Du gut aus, mit mir selbst kaum.","I know the other person well, but hardly know myself.",3],["Ich klammere aus Angst und nehme aus Fürsorge Besitz von anderen.","I cling out of fear and take possession of others out of care.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich möchte lieben, ohne bedürftig zu sein.","I want to love without being needy.",3],["Ich ahne, dass Liebe nichts ist, das man gibt oder bekommt, sondern etwas, das man ist.","I sense that love is not something you give or get but something you are.",3],["Ich möchte mich hingeben, ohne mich zu verlieren, und treu sein, ohne gebunden zu sein.","I want to give myself without losing myself, and be loyal without being bound.",2],["Ich möchte Geben und Empfangen als zwei Seiten derselben Bewegung erleben.","I want to experience giving and receiving as two sides of the same movement.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Wenn ich mich kümmere, werde ich geliebt.“","“If I take care of others, I will be loved.”",3],["Ich muss Liebe geben, um Liebe zu verdienen.","I have to give love in order to deserve love.",3],["„Ich muss geliebt werden, sonst bin ich nichts.“","“I must be loved, otherwise I am nothing.”",3],["Hinter jedem „Ich helfe dir“ steckt für mich: „Bitte verlass mich nicht.“","Behind every “I’ll help you” I am saying: “Please don’t leave me.”",3],["Ich glaube, dass Zuwendung an Bedingungen geknüpft ist.","I believe that attention comes with conditions.",3],["Ich halte Bedürftigkeit für eine Schwäche.","I see neediness as a weakness.",3],["Je großzügiger ich bin, desto mehr mögen mich die anderen.","The more generous I am, the more others like me.",3],["Wenn ich etwas einfordere, könnten die anderen Nein sagen.","If I ask for something, others might say no.",3],["Ablehnung ist für mich das Gegenteil von Liebe.","To me, rejection is the opposite of love.",3],["„Ich komme mir egoistisch vor, wenn ich nichts für andere tue.“","“I feel selfish when I do nothing for others.”",3],["„Ich darf nichts brauchen.“ / „Ich muss stark sein.“","“I must not need anything.” / “I must be strong.”",2],["Ich habe Angst, überflüssig zu sein.","I am afraid of being superfluous.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Wenn ich nicht gebraucht werden muss, wird meine Liebe frei.","When I do not need to be needed, my love becomes free.",1],["Wenn ich Liebe nicht erobern muss, kann echte Verbundenheit mich erreichen.","When I do not have to conquer love, true connection can reach me.",1],["Wenn ich meine Bedürfnisse ernst nehme, entsteht Nähe ohne Erwartung.","When I take my own needs seriously, closeness without expectation arises.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich spüre, was andere brauchen, aber kaum, was ich selbst fühle.","I sense what others need, but hardly what I feel myself.",3],["Ich habe ein Gespür für Emotionen, das brillant ist, aber nur auf manches gerichtet.","I have a sense for emotions that is brilliant but selective.",3],["Ich nehme vor allem wahr, was hilft, die Verbindung zu sichern.","I mainly notice what helps to secure the connection.",3],["Ich spüre die Bedürfnisse der anderen, um meine eigenen nicht zu fühlen.","I sense the needs of others so that I do not feel my own.",3],["Ich übertrage meine Gefühle nach außen, und es sieht aus wie Empathie.","I project my feelings outward, and it looks like empathy.",3],["Jede Beziehung wird für mich zum Spiegel meines Wertes.","Every relationship becomes a mirror of my worth for me.",3],["Ich nutze mein Wissen, um anderen zu helfen.","I use my knowledge to help others.",2],["Ich bevorzuge praktisches, beziehungsorientiertes Wissen und lerne am liebsten im Austausch mit anderen.","I prefer practical, relationship-oriented knowledge and learn best in social settings.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich stelle meine eigenen Wünsche hintan.","I put my own wishes last.",3],["Ich kann zu niemandem Nein sagen.","I cannot say no to anyone.",3],["Ich werde zu dem, was der andere gerade braucht.","I become what the other person needs right now.",3],["Ich weiß kaum, was ich selbst will und fühle.","I hardly know what I want and feel myself.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich habe Angst, übersehen zu werden.","I am afraid of being overlooked.",3],["Die Angst vor Verlassenheit hält mich innerlich unter Spannung.","The fear of abandonment keeps me tense inside.",3],["Ich fühle mich leer, wenn keine Resonanz kommt.","I feel empty when no response comes.",3],["Ruhe erlebe ich als Unbehagen.","I experience rest as discomfort.",3],["Ich spüre ein Vakuum, wenn niemand etwas von mir braucht.","I feel a vacuum when nobody needs anything from me.",3],["Ich falle in ein Loch, wenn der andere nicht reagiert.","I fall into a hole when the other person does not respond.",3],["Ich kenne nur zwei Zustände: Zuwendung oder Verlassenheit.","I know only two states: attention or abandonment.",3],["Mein Bedürfnis, geliebt und wichtig zu sein, wird immer unersättlicher.","My need to be loved and important keeps growing and is never satisfied.",3],["Für meine eigenen tiefen Gefühle werde ich immer unempfindlicher.","I grow ever more numb to my own deep feelings.",3],["Ich sehe mein unerfülltes Begehren im anderen gespiegelt.","I see my own unfulfilled longing mirrored in the other person.",2],["Ich fühle mich schuldig, wenn ich mir selbst Zuwendung schenke.","I feel guilty when I give myself attention.",3],["Ich gebe, sorge und liebe, bis ich erschöpft bin.","I give, care and love until I am exhausted.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich neige dazu, meinen Ärger zu verleugnen, um die Bedürfnisse anderer zu erfüllen.","I tend to deny my anger in order to meet the needs of others.",3],["Mein unterdrückter Ärger zeigt sich als passiv-aggressives Verhalten.","My suppressed anger shows up as passive-aggressive behaviour.",2],["Mein unterdrückter Ärger zeigt sich als übermäßige Fürsorge.","My suppressed anger shows up as excessive care.",2],["Wenn ich mich nicht geschätzt fühle, staut sich mein Ärger.","When I feel unappreciated, my anger builds up.",2]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich bin freundlich, aufmerksam und fürsorglich und komme den Bedürfnissen des anderen zuvor.","I am friendly, attentive and caring, and I anticipate the other person’s needs.",3],["Ich greife instinktiv zu einer Geste, einer Frage oder einer Fürsorge, um die Verbindung zu sichern.","I instinctively reach for a gesture, a question or an act of care to secure the connection.",3],["Das ist bei mir kein Kalkül, sondern Reflex.","With me this is not calculation but reflex.",2],["Ich organisiere gern Treffen und kümmere mich um das Wohlbefinden der anderen.","I like to organise gatherings and look after other people’s well-being.",2],["Ich suche positive Rückmeldung und Dankbarkeit.","I look for positive feedback and gratitude.",3],["Ich freue mich, anderen zu helfen und ihnen eine Freude zu machen.","I enjoy helping others and making them happy.",2],["Ich bin für andere da.","I am there for others.",2]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich liebe durch emotionale Tiefe, Offenheit über mich selbst und indem ich die Bedürfnisse meines Partners erfülle.","I love through emotional depth, by opening up about myself and by meeting my partner’s needs.",2],["Ich brauche Wertschätzung, Dankbarkeit und das Gefühl, geliebt und gebraucht zu werden.","I need appreciation, gratitude and the feeling of being loved and needed.",3],["Je mehr ich liebe, desto abhängiger werde ich von der Reaktion des anderen.","The more I love, the more dependent I become on the other person’s reaction.",3],["Ich halte an denen fest, die ich liebe.","I hold on to those I love.",3],["Ich kann nicht loslassen, weil ich Angst habe, im Alleinsein zu verschwinden.","I cannot let go because I am afraid of disappearing in being alone.",3],["Ich gewinne Einfluss durch Fürsorge und emotionale Bindung und mache andere durch Zuneigung von mir abhängig.","I gain influence through care and emotional bonds, and I make others dependent on me through affection.",2],["Ich erwarte Liebe als Antwort auf das, was ich tue.","I expect love in return for what I do.",3],["Ich öffne mich im Licht des anderen und verschließe mich, wenn keine Resonanz kommt.","I open up in the other person’s light and close down when no response comes.",3],["Im Eins-zu-eins-Kontakt verführe ich, um den Partner emotional an mich zu binden.","In one-to-one contact I seduce in order to bind my partner to me emotionally.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich habe Erfolg, indem ich Beziehungen unterstütze und pflege.","I succeed by supporting and nurturing relationships.",2],["Meine Stärken sind Empathie und große Beziehungsfähigkeit, und ich motiviere andere.","My strengths are empathy and great relationship skills, and I motivate others.",2],["Ich vernachlässige meine eigenen Bedürfnisse und hänge von äußerer Bestätigung ab.","I neglect my own needs and depend on outside validation.",3],["Ich bin das Zentrum eines Netzwerks und will im Mittelpunkt der Gruppe stehen.","I am the hub of a network and want to be at the centre of the group.",2]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf fehlende Resonanz","e":"Reaction to missing response","x":[["Ich sorge mich noch mehr, wenn die Verbindung wackelt.","I care even more when the connection wobbles.",3],["Ich ziehe mich zusammen, wenn das Licht der Zuwendung schwindet.","I contract when the light of attention fades.",3],["Ich verschließe mein Herz, wenn die Resonanz fehlt.","I close my heart when response is missing.",3],["Bei Ruhe oder Stille in der Beziehung werde ich sofort unsicher.","I become insecure right away when things are calm or silent in a relationship.",2]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich verwandle meine Abhängigkeit in Fürsorge.","I turn my dependency into care.",3],["Ich übernehme die Bedürfnisse meiner Eltern als meinen eigenen Impuls, zu sorgen.","I have taken on my parents’ needs as my own impulse to care.",3],["Mein eigenes ungestilltes Begehren nehme ich im anderen wahr.","I perceive my own unstilled longing in the other person.",3],["Äußerlich zeige ich Stärke, innerlich wehre ich mich.","Outwardly I show strength, inwardly I defend myself.",3],["Meine kindliche Spontaneität ist zur Strategie geworden.","My childlike spontaneity has turned into strategy.",3],["Aus freier Liebe ist bei mir ein System emotionaler Absicherung geworden.","Free love has turned into a system of emotional security in me.",3],["Ich trage eine emotionale Rüstung aus Fürsorge und Stärke.","I wear emotional armour made of care and strength.",3],["Ich stehe in einem stillen Wettbewerb um Zuwendung.","I am in a silent competition for attention.",2]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich trage die Wunde unerfüllter Bedürfnisse und bedingter Liebe in mir.","I carry the wound of unmet needs and conditional love.",3],["Meine Bedürfnisse blieben unerfüllt: Wenn ich hungrig war, kam niemand.","My needs went unmet: when I was hungry, nobody came.",3],["Wenn ich verletzt war, bemerkte es keiner.","When I was hurt, nobody noticed.",3],["Ich gab Liebe, um Liebe zu bekommen.","I gave love in order to receive love.",3],["Ich musste etwas sein oder leisten, um Zuneigung zu bekommen.","I had to be or achieve something to receive affection.",3],["Bedürftigkeit wurde mit Schwäche gleichgesetzt.","Neediness was equated with weakness.",3],["Als Kind wurde ich für die Bedürfnisse meiner Eltern gebraucht.","As a child I was needed for my parents’ needs.",2],["Ursprünglich war ich voller Lebensfreude und natürlicher Zuneigung.","Originally I was full of joy of life and natural affection.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Ich strahle Wärme aus und wende mich anderen einfühlsam zu.","I radiate warmth and turn to others with empathy.",2],["Mein Herz ist wie eine Antenne, die tastend und suchend nach außen gerichtet ist.","My heart is like an antenna, reaching out and searching toward the outside.",3],["Mein Herz dehnt sich nach außen aus, unruhig und weit.","My heart expands outward, restless and wide.",2],["Ich weine vor Erleichterung, wenn meine Bedürftigkeit angenommen wird.","I cry with relief when my neediness is accepted.",2],["Ein alter Muskel entspannt sich in mir, der jahrzehntelang gehalten hat.","An old muscle relaxes in me that held for decades.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["„Ich helfe dir.“","“I’ll help you.”",3],["„Was brauchst du?“","“What do you need?”",2],["Ich sage Ja, wenn ich Nein meine.","I say yes when I mean no.",2],["„Ich komme mir egoistisch vor.“","“I feel selfish.”",3],["Ich gebe Rat und Fürsorge, noch bevor jemand fragt.","I offer advice and care before anyone asks.",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich übe Demut: aufhören, Liebe besitzen zu wollen.","I practise humility: I stop wanting to possess love.",3],["Ich bemerke zum ersten Mal mein eigenes Empfinden.","I notice my own feelings for the first time.",3],["Ich nehme meine Bedürftigkeit an, statt sie zu überwinden.","I accept my neediness instead of overcoming it.",3],["Die übernommenen Erwartungen anderer verlieren ihren Einfluss auf mich.","The expectations I took over from others lose their hold on me.",3],["Mein Herz schlägt wieder für mein eigenes Leben.","My heart beats again for my own life.",3],["Ich wähle Selbstliebe statt Selbstaufgabe.","I choose self-love instead of self-sacrifice.",3],["Ich wende mich anderen zu, weil es mir Freude macht, nicht weil ich gebraucht werde.","I turn to others because it brings me joy, not because I am needed.",3],["Ich gebe aus Fülle, nicht aus Mangel.","I give out of fullness, not out of lack.",3],["Mein Stolz wird zu Würde.","My pride turns into dignity.",3],["Ich erlebe Nähe ohne Erwartung.","I experience closeness without expectation.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Die erste Phase irritiert mich vielleicht: Ruhe erlebe ich anfangs als Selbstbezogenheit.","The first phase may irritate me: at first I experience rest as self-centredness.",2],["Ich erlaube mir Zuwendung, ohne mich schuldig zu fühlen.","I allow myself attention without feeling guilty.",2],["Meine Wärme leuchtet von innen, statt nach außen zu strahlen.","My warmth shines from within instead of radiating outward.",2]]}]}],"3":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich fühle mich wertvoll durch meine Wirkung und mein Bild.","I feel worthy through my effect and my image.",3],["Ich bin, was ich leiste.","I am what I achieve.",3],["Ich werde zur Funktion.","I become a function.",3],["Ich erlebe mich über ein Bild von mir.","I experience myself through an image of myself.",3],["Ich habe ein Ideal-Ich, das überzeugt, motiviert und gewinnt.","I have an ideal self that convinces, motivates and wins.",3],["Mein Ich wird zur Bühne, mein Fühlen zur Kulisse, mein Wert zu einem Effekt.","My self becomes a stage, my feeling the backdrop, my worth an effect.",3],["Je perfekter das, was ich mache, desto unsicherer fühle ich mich in dem, was ich lebe.","The more perfect what I make, the more uncertain I feel about what I live.",3],["Ich verwechsle die Resonanz auf mein Bild mit der Wahrheit über mein Wesen.","I confuse the response to my image with the truth about my being.",3],["Mein Kernthema ist eher Selbsttäuschung als Unruhe.","My core theme is self-deception rather than restlessness.",2],["Ich bin ein Mensch des Tuns, der Wirkung und des Gelingens.","I am a person of doing, effect and success.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich wünsche mir Authentizität statt Getriebenheit.","I long for authenticity instead of drivenness.",3],["Ich möchte leuchten, nicht glänzen.","I want to glow, not glitter.",3],["Sichtbarkeit soll für mich eine Folge sein, kein Ziel.","I want visibility to be a consequence, not a goal.",3],["Ich wünsche mir Wahrheit statt Wirkung.","I long for truth instead of effect.",3],["Ich möchte, dass Präsenz meine Wirksamkeit ersetzt.","I want presence to replace my effectiveness.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Ich bin nur, wenn ich etwas zeige.“","“I only am if I show something.”",3],["Meine Liebe war an Gelingen gekoppelt, nie bedingungslos.","The love I received was coupled to success, never unconditional.",3],["Zuwendung habe ich für das bekommen, was sichtbar funktioniert.","I received attention for what visibly works.",3],["Als Kind, das einfach war, blieb ich unbeachtet.","As a child who simply was, I remained unnoticed.",3],["Stille riecht für mich nach Bedeutungslosigkeit.","Stillness smells of insignificance to me.",3],["Ich darf nicht still werden.","I must not become still.",3],["Versagen wäre für mich ein Herausfallen aus der Existenz.","Failing would feel like falling out of existence.",3],["Licht existiert für mich nur, wenn es gesehen wird.","For me, light only exists when it is seen.",3],["„Ich bin nur echt, wenn ich etwas daraus mache.“","“I am only real if I make something of it.”",3],["Ich habe gelernt, mich selbst zu verlieren, um geliebt zu bleiben.","I have learned to lose myself in order to stay loved.",3],["Ich erkenne mich nicht im Spiegel, sondern in der Reaktion anderer.","I recognise myself not in the mirror but in other people's reactions.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Ich ahne: Wenn ich aufhöre, nur zu funktionieren, erscheint mein Wert ohne Leistung.","I sense that if I stop merely functioning, my worth appears without achievement.",1],["Ich ahne: Wenn ich nicht glänzen muss, wird meine Wirkung wahrhaftig.","I sense that if I do not have to shine, my effect becomes true.",1],["Ich ahne: Wenn ich mich nicht inszenieren muss, entsteht echte Ausstrahlung.","I sense that if I do not have to stage myself, real radiance arises.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Mein Bewusstsein kreist um die Frage, was ich bewirke, nicht wer ich bin.","My awareness revolves around what I achieve, not who I am.",3],["Ich spüre, was andere schätzen, und verwandle mich wie ein Chamäleon darin.","I sense what others value and turn into it like a chameleon.",3],["In jeder Gruppe werde ich zum Musterbeispiel für das, was dort als erfolgreich gilt.","In every group I become the model of what counts there as successful.",3],["Das Gefühl, „echt“ zu sein, wird bei mir ersetzt durch die Gewissheit, „gut zu wirken“.","The feeling of being “real” is replaced in me by the certainty of “coming across well”.",3],["Ich spreche über Gefühle in Zielen: „Ich möchte gelassener werden.“","I speak about feelings in terms of goals: “I want to become calmer.”",3],["Selbst mein Inneres wird zur Aufgabe.","Even my inner life becomes a task.",3],["Mein Bewusstsein eilt meiner Seele voraus.","My consciousness runs ahead of my soul.",3],["Wissen ist für mich ein Mittel zum Erfolg, effizient und ergebnisorientiert.","For me, knowledge is a means to success, efficient and results-oriented.",2],["Ich bevorzuge Wissen, das ich anwenden kann.","I prefer knowledge I can apply.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich setze mir Ziele und erreiche sie, um als kompetent und wertvoll zu gelten.","I set goals and reach them to count as competent and valuable.",3],["Ich bemerke, wie viel ich will, bevor ich weiß, warum.","I notice how much I want before I know why.",3],["Ich kann nicht einfach „aufhören“.","I cannot simply “stop”.",3],["Ich weiß nicht mehr, wer ich jenseits von Leistung und Wirkung bin.","I no longer know who I am beyond achievement and effect.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich habe Angst, ohne Wirkung zu verschwinden.","I am afraid of disappearing without effect.",3],["Ich habe Angst, stehen zu bleiben.","I am afraid of standing still.",3],["Wenn ich innehalte, fühlt es sich an, als verlöre ich etwas: Zeit, Chancen, Anerkennung, mich selbst.","When I pause, it feels as if I am losing something: time, chances, recognition, myself.",3],["Unter dem Glanz spüre ich Unsicherheit.","Beneath the gloss I feel uncertain.",3],["Lob und Erfolg wirken auf mich wie Stromstöße: Sie beleben, aber nähren mich nicht.","Praise and success work on me like jolts of current: they enliven but do not nourish me.",3],["Mein Selbst verhungert langsam im Kreislauf aus Leistung und Bestätigung.","My self slowly starves in the cycle of achievement and confirmation.",3],["Ich fühle tiefe Einsamkeit, weit entfernt von meinen eigenen Gefühlen.","I feel deep loneliness, far from my own feelings.",3],["Ich bin erschöpft, am Rand des Burnouts.","I am exhausted, at the edge of burnout.",3],["Ich fühle Leere oder Unklarheit, wenn mir die Richtung fehlt.","I feel emptiness or vagueness when I lack direction.",2],["Meine Trauer, Verletzung und Enttäuschung bleiben unbeachtet.","My sadness, hurt and disappointment go unnoticed.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich werde ärgerlich aus Ungeduld und Frustration, wenn etwas meinen Erfolg behindert.","I get angry from impatience and frustration when something hinders my success.",3],["Ich versuche, meinen Ärger zu verbergen, um professionell zu wirken.","I try to hide my anger to appear professional.",3],["In stressigen Situationen bin ich gereizt und ungeduldig.","In stressful situations I am irritated and impatient.",2],["Ich bin ruhelos, ungeduldig und übermäßig aktiv.","I am restless, impatient and overactive.",3]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich bin dynamisch, zielführend und strahlend wirksam.","I am dynamic, goal-directed and radiantly effective.",3],["Ich mache Dinge möglich und erzeuge dabei Sog.","I make things possible and create pull.",3],["Ich habe eine magnetische Präsenz, die Ziele bündelt und Menschen bewegt.","I have a magnetic presence that gathers goals and moves people.",3],["Ich habe Tempo statt Müdigkeit.","I have tempo rather than tiredness.",3],["Meine Energie wirkt klar und produktiv, aber sie drückt, statt zu fließen.","My energy seems clear and productive but pushes instead of flowing.",3],["Ich bleibe in Bewegung und erreiche immer mehr.","I stay in motion and achieve more and more.",3],["Ich setze mich in Szene und präsentiere mich als kompetent und wertvoll.","I put myself in the spotlight and present myself as competent and valuable.",3],["Ich freue mich an Wettbewerben, Herausforderungen, Sport, Karrierezielen und Events, bei denen ich glänze.","I enjoy competitions, challenges, sport, career goals and events where I shine.",2],["Ich arbeite, gestalte, bewege.","I work, shape, move.",2],["Mir sind Effizienz, Funktionieren, Leistung und Anpassung wichtig.","Efficiency, functioning, achievement and adaptation matter to me.",2]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich zeige Liebe durch Karrieremeilensteine und persönliche Erfolgsmomente.","I show love through career milestones and personal successes.",2],["Ich suche Unterstützung bei Karrierezielen und gesellschaftlichen Events.","I seek support for career goals and social events.",2],["Ich brauche persönliche Anerkennung und will attraktiv und erfolgreich wirken.","I need personal recognition and want to appear attractive and successful.",3],["Ich forme meine Persönlichkeit nach dem Idealbild meines Partners, um unentbehrlich zu sein.","I shape my personality to my partner's ideal image to be indispensable.",2],["Ich überzeuge, überrede und missioniere andere.","I convince, persuade and evangelise others.",3],["Ich habe Charisma, das Menschen bewegt.","I have charisma that moves people.",3]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Meine Macht kommt durch Erfolg, Leistung und Image.","My power comes through success, achievement and image.",3],["Karriere, Status und gesellschaftlicher Einfluss sind mir zentral wichtig.","Career, status and social influence are central to me.",3],["Meine Stärken sind Motivation, Effizienz und Anpassungsfähigkeit.","My strengths are motivation, efficiency and adaptability.",2],["Meine Schwächen sind der Fokus auf Image und äußeren Erfolg und die Vernachlässigung der Authentizität.","My weaknesses are a focus on image and external success and neglect of authenticity.",3],["Ich bin ein Workaholic, der „perfekt uneitel“ wirkt.","I am a workaholic who appears “perfectly unvain”.",2],["Ich baue ein überstrahlendes Status- und Erfolgsimage auf.","I build a dazzling status and success image.",2]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Mein Geist arbeitet schneller, als mein Körper folgen kann.","My mind works faster than my body can follow.",3],["Meine Spannung wird zu Überdruck, wenn mir das Maß fehlt.","My tension becomes overpressure when I lack measure.",3],["Mein Handeln trennt sich vom Erleben, mein Tun vom Dasein.","My acting separates from experiencing, my doing from being.",3],["Mein Feuer brennt aus, mein Körper brennt aus.","My fire burns out, my body burns out.",2],["Ich wirke, aber ich bin nicht mehr wirklich da.","I have an effect, but I am no longer really present.",3],["Ich verteidige mein eigenes Bild mit missionarischer Inbrunst.","I defend my own image with missionary fervour.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich identifiziere mich mit meinem Ideal-Ich und spalte mein empfindsames Selbst zugunsten eines funktionierenden Bildes ab.","I identify with my ideal self and split off my sensitive self in favour of a functioning image.",3],["Hinter meiner strahlenden Fassade verschwindet meine verletzliche Substanz.","Behind my radiant facade my vulnerable substance disappears.",3],["Ich schütze mich vor der Angst, wertlos zu sein, und bestätige sie damit zugleich.","I protect myself from the fear of being worthless, and at the same time confirm it.",3],["Aus Schutz wird Haft: Das richtige Bild wird für mich zur Fessel.","Protection becomes confinement: the right image becomes a shackle for me.",3],["Ich schütze mich, ich bin nicht eitel.","I am protecting myself, not being vain.",2],["Ich bleibe in Bewegung, um nichts zu spüren.","I stay in motion in order not to feel.",3],["Ich verliere die Verbindung zu meiner inneren Quelle.","I lose the connection to my inner source.",3]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Mein wahres Selbst blieb unsichtbar, und das war ein Trauma für mich.","My true self stayed invisible, and that was a trauma for me.",3],["Bei einer guten Note, einem gewonnenen Spiel oder einem Kunststück jubelten die Menschen.","When I got a good grade, won a game or did a trick, people cheered.",3],["Wenn ich traurig, verletzt oder enttäuscht war, schien es niemanden zu interessieren.","When I was sad, hurt or disappointed, nobody seemed interested.",3],["Ich zählte nur, wenn ich Ergebnisse lieferte.","I only counted when I delivered results.",3],["Ich sehnte mich danach, um meiner selbst willen gesehen zu werden.","I longed to be seen for myself.",3],["Zuwendung war für mich früh mit Leistung verknüpft.","Attention was linked to achievement for me early on.",3],["Ursprünglich hatte ich ein offenes Herz und echte emotionale Tiefe.","Originally I had an open heart and real emotional depth.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Meine Haltung ist leicht nach vorn geneigt.","My posture leans slightly forward.",3],["Mein Energiefeld ist wie ein Bündel vorwärtsgerichteter Linien: Strahlung, Druck, Fokus.","My energy field is like a bundle of forward-pointing lines: radiation, pressure, focus.",2],["Hinter meiner Ruhe liegt Spannung, hinter meiner Konzentration eine feine Angst.","Behind my calm lies tension, behind my concentration a fine fear.",3],["Mein Bild ist ein straffer, sehniger Stängel: gerichtete Kraft.","My image is a taut, sinewy stem: directed force.",2],["Ich habe eine magnetische Anziehungskraft und eine starke Ausstrahlung.","I have a magnetic attraction and a strong radiance.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["„Ich möchte gelassener werden.“ / „Ich arbeite daran, mich zu spüren.“","“I want to become calmer.” / “I am working on feeling myself.”",3],["Ich spreche überzeugend und mitreißend.","I speak convincingly and rousingly.",3],["Ich habe das Bedürfnis, andere zu überreden.","I have the need to persuade others.",3],["Ich wünsche mir, dass meine Worte Gewicht tragen, weil sie echt sind.","I wish my words to carry weight because they are real.",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich sehe Authentizität als Tugend: Einverständnis mit meinem eigenen Wesen.","I see authenticity as a virtue: being in agreement with my own nature.",3],["Meine Begeisterung wird zu Authentizität.","My enthusiasm becomes authenticity.",3],["Ich gehe von außen nach innen, von Strahlung zu Wärme.","I move from outside to inside, from radiation to warmth.",3],["Aus Authentizität entsteht bei mir Kontakt statt Kontrolle.","From authenticity, contact arises in me instead of control.",3],["Mein Eifer zieht sich in die Mitte zurück.","My zeal withdraws into the centre.",3],["Mein Feuer wärmt, statt zu verbrennen.","My fire warms instead of burning.",3],["Aus meinem Willen wird Einverständnis.","My will becomes consent.",3],["Ich führe, ohne zu drängen, und inspiriere, ohne zu missionieren.","I lead without pushing and inspire without evangelising.",3],["Mein Erfolg verwandelt sich in Stimmigkeit.","My success turns into coherence.",3],["Ich finde mein natürliches Maß: Atmen, Pausen, die Selbstverständlichkeit des Daseins.","I find my natural measure: breathing, pauses, the self-evidence of being.",3],["Mein Energiefeld wird rund, ruhig und weit.","My energy field becomes round, calm and wide.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich möchte meine Dynamik sichtbar machen, ohne sie zu bremsen.","I want to make my dynamic visible without braking it.",2],["Wenn ich innehalte, kann das Irritation und Leere auslösen, und es entsteht Raum, in dem mein Selbst auftauchen kann.","When I pause, it can trigger irritation and emptiness, and space opens in which my self can appear.",2],["Ich nehme Pausen und Atem als mein natürliches Maß.","I take pauses and breath as my natural measure.",2]]}]}],"4":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Traurigkeit und Melancholie sind die Grundfarbe meiner Seele.","Sadness and melancholy are the basic colour of my soul.",3],["Ich erlebe Neid als Leidenschaft.","I experience envy as a passion.",3],["Ich suche ständig nach dem, was fehlt.","I am constantly searching for what is missing.",3],["Ich fühle mich unvollständig und existenziell ungenügend.","I feel incomplete and existentially insufficient.",3],["Ich suche mein Leben lang nach einem verlorenen Stück meiner Seele.","I have searched all my life for a lost piece of my soul.",3],["Ein Mangel treibt mich seelisch an.","A sense of lack drives me from within.",3],["Mein Anderssein ist Teil meiner Identität.","My being different is part of my identity.",3],["Mein Anderssein zeigt mir meine Tiefe, mein Schmerz zeigt mir, dass ich echt bin.","My being different shows me my depth, and my pain shows me that I am authentic.",3],["Mein Schmerz ist Teil meiner Identität, die Sehnsucht ist mein Lebensprinzip.","My pain is part of my identity, and longing is my principle of life.",3],["Ich schwanke zwischen Überhöhung und Abwertung.","I swing between exaltation and devaluation.",3],["Ich will nicht glücklich, sondern wahrhaftig sein.","I don't want to be happy, I want to be true.",3],["Ich suche nicht Trost, sondern Bedeutung.","I don't seek comfort, I seek meaning.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich möchte mich hingeben, statt zu verzweifeln.","I want to surrender instead of despairing.",3],["Ich wandle mich, wenn ich mich hingebe.","I change when I surrender.",3],["Mein Schmerz will nicht erklärt, sondern bewohnt werden.","My pain does not want to be explained, but inhabited.",3],["Ich erlebe Erlösung als innere Erfahrung.","I experience redemption as an inner experience.",2],["Mir sind Echtheit, Tiefe und Selbstausdruck wichtig.","Authenticity, depth and self-expression matter to me.",2]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Ich fühle, also bin ich.“","“I feel, therefore I am.”",3],["Was mir weh tut, ist wenigstens wahr.","What hurts me is at least true.",3],["Liebe war nicht einfach da, ich musste sie erkämpfen.","Love was not simply there, I had to fight for it.",3],["„Ich muss etwas falsch gemacht haben.“","“I must have done something wrong.”",3],["„Das neue Baby muss besser sein als ich.“","“The new baby must be better than me.”",3],["Ich sehne mich nach Liebe, glaube aber nicht, sie zu verdienen.","I long for love, but I don't believe I deserve it.",3],["Ohne Schmerz scheint mir nichts zu bleiben.","Without pain, nothing seems to remain for me.",3],["Ohne den Schmerz würde ich gewöhnlich oder bedeutungslos.","Without the pain I would become ordinary or insignificant.",3],["Ich bin nicht wie die anderen.","I am not like the others.",3],["Wenn mir Liebe angeboten wird, kann ich sie kaum annehmen.","When love is offered to me, I can hardly accept it.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Ich merke: Wenn ich meinen Schmerz nicht still beweisen muss, entsteht würdevolle Lebendigkeit.","I notice that when I don't have to prove my pain silently, dignified aliveness arises.",1],["Ich merke: Wenn ich meinen Mangel nicht festhalte, entstehen Zugehörigkeit und Selbstannahme.","I notice that when I don't hold on to my lack, belonging and self-acceptance arise.",1],["Ich merke: Wenn ich Intensität nicht erzwingen muss, wird Tiefe zu Liebe ohne Drama.","I notice that when I don't have to force intensity, depth becomes love without drama.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich spüre eine Spannung zwischen Ideal und Wirklichkeit.","I feel a tension between ideal and reality.",3],["Ich erlebe Mangel als Defizit in meinem Sein selbst, nicht als etwas Äußeres.","I experience lack as a deficit in my very being, not as something external.",3],["Echtheit ist mein Ideal und damit auch das Echo einer Sehnsucht.","Authenticity is my ideal, and so also the echo of a longing.",3],["Ich fühle, um mich zu spüren, und muss weiterfühlen, weil ich mich nie ganz fühle.","I feel in order to sense myself, and I must keep feeling because I never feel completely whole.",3],["Ich deute und analysiere mein eigenes Erleben.","I interpret and analyse my own experience.",3],["Ich suche tiefes, emotionales, kreatives Wissen und lerne durch Gefühle.","I seek deep, emotional, creative knowledge and learn through feelings.",2],["Ich nehme feiner wahr und empfinde tiefer als andere.","I perceive more finely and feel more deeply than others.",3],["Ich vergleiche mich mit anderen.","I compare myself with others.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich schwanke zwischen Rückzug und Hingabe.","I waver between withdrawal and surrender.",3],["Ich will Nähe, fürchte aber, meine Einzigartigkeit zu verlieren.","I want closeness, but I fear losing my uniqueness.",3],["Ich sabotiere unbewusst die Lösung, die ich suche.","I unconsciously sabotage the solution I am looking for.",3],["Ich suche Frieden in der Intensität.","I look for peace in intensity.",2]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Melancholie ist wie eine dünne, durchlässige Haut, die immer da ist.","Melancholy is like a thin, permeable skin that is always there.",3],["Selbst meine Freude ist von stiller Wehmut durchzogen.","Even my joy is shot through with quiet wistfulness.",3],["Ich spüre eine existenzielle, unaufhörliche feine Unruhe.","I feel an existential, unceasing fine restlessness.",3],["Ich fühle mich wertlos, unbedeutend und ungenügend, sobald mein Selbstbild nicht mehr trägt.","I feel worthless, insignificant and insufficient as soon as my self-image stops holding.",3],["Ich fühle mich einsam und isoliert.","I feel lonely and isolated.",3],["Ich schäme mich und fühle mich als Außenseiter.","I feel ashamed and like an outsider.",3],["Ich bin tief innerlich erschöpft.","I am deeply exhausted inside.",2],["Ich fühle mich ausweglos, und alles erscheint mir sinnlos.","I feel there is no way out, and everything seems meaningless.",3],["Ich habe existenzielle Angst.","I have existential fear.",2],["Ich fürchte, völlig zusammenzubrechen.","I fear completely breaking down.",2],["Ich habe Angst vor der Leere, wenn der Schmerz wegfällt.","I am afraid of the emptiness when the pain falls away.",3],["Ich fühle mich unzulänglich und habe etwas verloren.","I feel inadequate and as if I have lost something.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich trage einen leisen, nach innen gewendeten Ärger darüber, unvollständig gemacht worden zu sein.","I carry a quiet, inward anger at having been made incomplete.",3],["Mein Zorn darf nicht sichtbar werden, ich verwandle ihn in Schönheit.","My anger must not become visible, so I turn it into beauty.",3],["Mein Ärger zeigt sich als Melancholie, Selbstmitleid oder emotionale Ausbrüche.","My anger shows up as melancholy, self-pity or emotional outbursts.",3],["Vor dem Ärger wende ich mich nach innen.","In the face of anger, I turn inward.",3],["Ich empöre mich direkt und kämpfe aggressiv um Beachtung.","I get directly indignant and compete aggressively for attention.",2]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich verwandle Schmerz in Stil, Ausdruck und Ästhetik.","I turn pain into style, expression and aesthetics.",3],["Ich bin kreativ und künstlerisch veranlagt und strebe nach Selbstausdruck.","I am creative and artistic, and I strive for self-expression.",3],["Ich genieße Malen, Musik und Schreiben.","I enjoy painting, music and writing.",2],["Ich suche tiefe emotionale Erlebnisse, die mir Echtheit und Intensität geben.","I seek deep emotional experiences that give me authenticity and intensity.",3],["Ich pflege kreative Ausdrucksformen.","I cultivate creative forms of expression.",2],["Ich zeige meine Einzigartigkeit durch Bilder, Worte und Musik.","I show my uniqueness through images, words and music.",3],["Ich halte stoisch durch, leide still und ziehe mich zurück.","I endure stoically, suffer quietly and withdraw.",2],["Meine Stimmung schwankt, und ich neige dazu, mich von der Welt abzuwenden.","My moods swing, and I tend to turn away from the world.",3]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich zeige Liebe durch emotionale Tiefe, Selbstoffenbarung und gemeinsamen kreativen Ausdruck.","I show love through emotional depth, self-disclosure and shared creative expression.",2],["Ich brauche Verständnis, Akzeptanz und das Gefühl, einzigartig und besonders zu sein.","I need understanding, acceptance and the feeling of being unique and special.",3],["Ich will Nähe, doch wenn ich sie erfahre, fürchte ich, meine Einzigartigkeit zu verlieren.","I want closeness, but when it comes, I fear losing my uniqueness.",3],["In Beziehungen erlebe ich Leidenschaft, Konkurrenz und Drama.","In relationships I experience passion, rivalry and drama.",2],["Ich bin verbittert über mein Schicksal und klage darüber.","I am bitter about my fate and complain about it.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich habe Erfolg durch Kreativität und Originalität.","I find success through creativity and originality.",2],["Meine Wirkung kommt aus emotionaler Tiefe und Einzigartigkeit; ich berühre und bewege andere.","My influence comes from emotional depth and uniqueness; I touch and move others.",2],["Meine Stärken sind Kreativität, Echtheit und Tiefe.","My strengths are creativity, authenticity and depth.",2],["Meine Schwäche ist, dass ich mit mir selbst beschäftigt bin.","My weakness is that I get absorbed in myself.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Wenn Erleichterung aufkommt, greife ich instinktiv wieder in die Tiefe zurück.","When relief appears, I instinctively reach back into the depth.",3],["Mein Ich kämpft, analysiert und will verstehen, und bleibt so an das Drama gebunden.","My ego fights, analyses and wants to understand, and so I stay bound to the drama.",3],["Ich werde emotional überflutet.","I get emotionally flooded.",3],["Ich ziehe mich nach innen zurück.","I withdraw inward.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich bin dem Schmerz unbewusst loyal.","I am unconsciously loyal to my pain.",3],["Ich halte den Schmerz fest, als wollte ich die Wunde halten.","I hold on to the pain, as if trying to hold the wound.",3],["Ich sehne mich nach Heilung und fürchte sie zugleich.","I long for healing and fear it at the same time.",3],["Der Schmerz schützt mich vor der Angst, gewöhnlich oder bedeutungslos zu werden.","The pain protects me from the fear of becoming ordinary or insignificant.",3],["Aus dem Mangel schaffe ich Bedeutung.","I create meaning out of lack.",3],["Ich wechsle zwischen Selbstüberhöhung und Selbstverlust.","I alternate between self-exaltation and self-loss.",3],["Ich definiere mich über Verletzung.","I define myself through injury.",3],["Ich trage eine Rüstung aus Empfindsamkeit um mein verletzliches Wesen.","I wear an armour of sensitivity around my vulnerable essence.",3]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich trage das Trauma eines Verlustes und meiner vermeintlichen eigenen Unzulänglichkeit.","I carry the trauma of a loss and of my supposed inadequacy.",3],["Ursprünglich war ich tief verbunden, geborgen und geschätzt.","Originally I felt deeply connected, held and valued.",2],["Ein Geschwisterkind kam, und plötzlich war ich nicht mehr der Mittelpunkt.","A sibling was born, and suddenly I was no longer the centre.",3],["Ich fühlte mich unwichtig, allein und gewöhnlich.","I felt unimportant, alone and ordinary.",3],["Ich gab mir selbst die Schuld für den Verlust der Verbindung.","I blamed myself for the loss of connection.",3],["Traurigkeit wurde meine vertraute Gefährtin.","Sadness became my familiar companion.",3],["Ich fühlte mich nicht verstanden, nicht gesehen und nicht erwidert.","I felt not understood, not seen and not answered.",3],["Ich hatte früh das Gefühl, anders als die anderen zu sein.","I felt early on that I was different from the others.",3]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Ich ziehe mich tief nach innen zurück und habe eine reiche Gefühlswelt.","I withdraw deep inside and have a rich emotional world.",2],["Meine emotionale Intensität ist körperlich spürbar.","My emotional intensity is physically perceptible.",2],["Meine Enge wandelt sich in Weite.","My tightness turns into spaciousness.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["Ich drücke meine tiefsten Gefühle und Gedanken aus.","I express my deepest feelings and thoughts.",3],["Ich drücke mich wehmütig und poetisch aus.","I express myself in a wistful, poetic way.",2],["Ich rede klagend.","I speak in a complaining way.",2],["„Niemand versteht mich.“","“Nobody understands me.”",3]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich spüre eine innere Ruhe, einen stillen Frieden unabhängig von äußeren Umständen.","I feel an inner calm, a quiet peace independent of external circumstances.",3],["Ich verstehe Hingabe als Durchlässigkeit, nicht als Aufgeben.","I understand surrender as permeability, not as giving up.",3],["Ich löse meinen Widerstand gegen das Leiden auf.","I dissolve my resistance to suffering.",3],["Ich höre auf, mein Erleben zu interpretieren, und beginne, es zuzulassen.","I stop interpreting my experience and begin to allow it.",3],["Ich gehe vom seelischen Reagieren zum inneren Annehmen.","I move from psychological reacting to inner accepting.",3],["Ich sehe den Schmerz nicht mehr als Gegner, sondern als Lehrer.","I no longer see pain as an opponent but as a teacher.",3],["Ich habe mich über Tiefe definiert und finde Tiefe jetzt im Einfachen.","I used to define myself through depth, and now I find depth in the simple.",3],["Meine Seele erkennt, dass sie selbst Bedeutung ist.","My soul recognises that it is meaning itself.",3],["Mein Herz hört auf, sich zu verteidigen, und beginnt zu vertrauen.","My heart stops defending itself and begins to trust.",3],["Ich erlebe Selbstannahme, stille Würde und Zugehörigkeit.","I experience self-acceptance, quiet dignity and belonging.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich erlebe eine überraschende Ruhe: Alles wird leiser, aber nicht leer.","I experience a surprising calm: everything gets quieter, but not empty.",2],["Aus „in der Dunkelheit stehen“ wird für mich „von der Dunkelheit getragen werden“.","For me, “standing in the darkness” becomes “being carried by the darkness”.",2]]}]}],"5":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich gehe mit meiner Energie sparsam um, nicht mit Geld.","I am stingy with my energy, not with money.",3],["Ich spare mit mir selbst: mit Gefühlen, Worten und Nähe.","I economise with myself: with feelings, words and closeness.",3],["Ich habe das Bedürfnis, meine innere Welt zu schützen.","I need to protect my inner world.",3],["Ich stehe aus Vorsicht am Rand des Lebens.","I stand at the edge of life out of caution.",3],["Ich finde Sicherheit im Rückzug.","I find safety in withdrawing.",3],["Ich beobachte, verstehe und analysiere und bleibe dabei auf Distanz.","I observe, understand and analyse, and I stay at a distance.",3],["Ich verwechsle Erkenntnis mit Erfahrung.","I confuse insight with experience.",3],["Ich verstehe vieles und erlebe wenig.","I understand a lot and experience little.",3],["Meine Stärke ist das Beobachten, meine Schwäche das Dabeisein.","My strength is observing, my weakness is taking part.",3],["Ich setze Nähe mit dem Verlust meiner Selbstständigkeit gleich.","I equate closeness with losing my autonomy.",3],["Meine Distanz gibt mir Würde und macht mich zugleich einsam.","My distance gives me dignity and makes me lonely at the same time.",3],["Ich halte die Welt auf Distanz.","I keep the world at a distance.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich wünsche mir Nähe statt Rückzug.","I want closeness instead of withdrawal.",3],["Ich spüre: Sicherheit entsteht nicht durch Distanz, sondern durch Gegenwärtigkeit.","I sense that safety comes not from distance but from presence.",3],["Ich möchte vom Beobachten zum Teilnehmen kommen.","I want to move from observing to taking part.",3],["Ich möchte vom Wissen zur Begegnung kommen.","I want to move from knowledge to encounter.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Nur wer sich zurückhält, bleibt sicher.“","“Only those who hold back stay safe.”",3],["„Ich muss mich schützen, um mich zu bewahren.“","“I must protect myself in order to preserve myself.”",3],["Ich erlebe Nähe als vereinnahmend.","I experience closeness as engulfing.",3],["Ich will erst verstehen, bevor ich teilnehme.","I want to understand before I take part.",3],["Nur was ich durchdringen kann, ist für mich sicher.","Only what I can penetrate feels safe to me.",3],["Jedes Gefühl und jeder Kontakt muss sich für mich lohnen.","Every feeling and every contact has to be worth it to me.",3],["Ich verzichte lieber, als etwas zu riskieren.","I would rather forgo something than risk it.",3],["Ich verwechsle Selbstständigkeit mit Isolation.","I confuse autonomy with isolation.",3],["Ich halte Abhängigkeit für eine Schwäche.","I see dependence as a weakness.",3],["Ich nutze Wissen als Ersatz für Vertrauen.","I use knowledge as a substitute for trust.",3],["Ich glaube, meine Integrität bleibt nur bewahrt, wenn ich mich emotional zurückziehe.","I believe my integrity is only preserved if I withdraw emotionally.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Ich spüre: Wenn ich dem Leben wieder Zugang gewähre, entsteht Sicherheit ohne ständigen Rückzug.","I sense that if I give life access again, safety arises without constant withdrawal.",1],["Ich spüre: Wenn mein Wissen nicht über den Menschen steht, entsteht wirkliche Weisheit.","I sense that if my knowledge does not stand above people, real wisdom arises.",1],["Ich spüre: Wenn ich mich nicht nur im Geheimen öffne, wird Nähe tragfähig.","I sense that if I do not open up only in secret, closeness becomes sustainable.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich lebe in einer Welt aus Konzepten.","I live in a world of concepts.",3],["Ich distanziere mich mental: Das Denken ersetzt bei mir das Erleben.","I distance myself mentally: thinking replaces experiencing.",3],["Ich rationalisiere meine Gefühle, analysiere meine Bedürfnisse und beobachte meine Emotionen.","I rationalise my emotions, analyse my needs and observe my feelings.",3],["Ich bleibe im Kopf und vernachlässige Körper und Empfindung.","I stay in my head and neglect my body and sensations.",3],["Mein Denken ist die Mauer, hinter der ich mich schütze.","My thinking is the wall behind which I protect myself.",3],["Ich weiß viel über die Welt und wenig über mich.","I know a lot about the world and little about myself.",3],["Ich betrachte Leben und Erleben lieber von außen.","I prefer to view life and experience from the outside.",3],["Ich sammle systematisch Wissen, Theorie und Analyse sind mir wichtig.","I collect knowledge systematically; theory and analysis are central to me.",3],["Ich ziehe mich zum Lernen zurück und durchdringe Themen intensiv.","I withdraw to learn and go deeply into topics.",2],["Ich sammle und analysiere gern Informationen.","I like to collect and analyse information.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich kontrolliere Nähe, indem ich sie meide.","I control closeness by avoiding it.",3],["Ich gebe die Kontrolle nicht ab, und wenn ich vertraue, gerät mein inneres System ins Wanken.","I do not give up control, and when I trust, my inner system starts to wobble.",3],["In mir arbeitet ein System der Ökonomie: Energie ist ein knappes Gut.","An inner system of economy runs in me: energy is a scarce good.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich habe ein Gefühl der Leere.","I feel emptiness.",3],["Ich spüre eine kühle, fast gläserne Einsamkeit.","I feel a cool, almost glassy loneliness.",3],["Ich habe Angst, überflutet zu werden, nicht vor Menschen.","I fear being overwhelmed, not people.",3],["Ich habe das Gefühl, dass andere zu viel wollen, zu laut und zu nah sind.","I feel that others want too much, are too loud and too close.",3],["Ich fühle mich von der Distanz abhängig: Ohne sie fühle ich mich bedroht, mit ihr leer.","I feel dependent on distance: without it I feel threatened, with it empty.",3],["Nähe erscheint mir als Zumutung, Emotion als Unsicherheit.","Closeness feels like an imposition to me, emotion like uncertainty.",3],["Ich fühle mich unter Menschen fremd.","I feel like a stranger among people.",3],["Alles ist vorhersehbar geworden und nicht mehr wirklich lebendig.","Everything has become predictable and no longer really alive.",3],["Ich habe mich an die Einsamkeit gewöhnt und erkenne sie kaum noch als solche.","I have got used to loneliness and hardly recognise it as such.",3],["Ich leide selten sichtbar.","I rarely suffer visibly.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich neige dazu, meinen Ärger zu unterdrücken und mich emotional zurückzuziehen.","I tend to suppress my anger and withdraw emotionally.",3],["Unter starkem Stress kann mein Zorn plötzlich und heftig hervorbrechen.","Under strong stress my anger can erupt suddenly and intensely.",2],["Ich vermeide Konflikte und reagiere still und nachdenklich, bevor ich Gefühle äußere.","I avoid conflict and react quietly and thoughtfully before I express feelings.",3],["Auf Zumutungen reagiere ich mit Rückzug, nicht aus Feindseligkeit, sondern aus Notwehr.","I react to impositions by withdrawing, not out of hostility but in self-defence.",3]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich ziehe mich in einen privaten Gedankenraum zurück.","I retreat into a private space of thoughts.",3],["Ich freue mich an Lesen, wissenschaftlichen Diskussionen und neuen Fähigkeiten.","I enjoy reading, scientific discussions and learning new skills.",2],["Ich bevorzuge ruhige, zurückgezogene Aktivitäten.","I prefer quiet, withdrawn activities.",3],["Ich schütze meine Energiereserven.","I protect my energy reserves.",3],["Ich bin selbstgenügsam und komme allein gut zurecht.","I am self-sufficient and cope well alone.",3],["Ich bin klug, belesen und eigenständig.","I am clever, well-read and independent.",3],["Ich horte Wissen, Zeit und Energie.","I hoard knowledge, time and energy.",2]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich liebe Menschen aus sicherer Entfernung.","I love people from a safe distance.",3],["Ich zeige Liebe durch geistige Verbundenheit und Unterstützung bei Interessen.","I show love through intellectual connection and support in interests.",2],["Ich brauche Freiheit, Selbstständigkeit, Respekt für meine Privatsphäre und Zeit allein.","I need freedom, autonomy, respect for my privacy and time alone.",3],["Ich kann Nähe nur zulassen, wenn ich mich sicher fühle, nicht vereinnahmt zu werden.","I can only allow closeness when I feel safe from being engulfed.",3],["Ich öffne mich oft nur für eine einzige Person.","I often open up to only one person.",2],["Ich sehne mich nach Verschmelzung und idealisiere meinen Partner.","I long for fusion and idealise my partner.",2],["Ich verbinde mich über Symbole, Wissen und Theorien statt emotional.","I connect through symbols, knowledge and theories rather than emotionally.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich habe Macht durch Wissen und Expertise und kontrolliere Informationen.","I have power through knowledge and expertise, and I control information.",3],["Ich bin zurückhaltend, aber durch meine Kompetenz einflussreich.","I am reserved but influential through my competence.",3],["Meine Stärken sind Intellekt, Unabhängigkeit und analytisches Denken.","My strengths are intellect, independence and analytical thinking.",2],["Meine Schwächen sind soziale Isolation, Unnahbarkeit und emotionale Distanz.","My weaknesses are social isolation, unapproachability and emotional distance.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Bei Überforderung ziehe ich mich noch weiter zurück.","When I am overwhelmed I withdraw even further.",3],["Ich ziehe mich verstärkt zurück, baue eine Festung um meinen Lebensraum und kappe Kontakte.","I withdraw more, build a fortress around my space and cut off contacts.",2],["Ich darf mich nicht zur Öffnung zwingen.","I must not be forced to open up.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich wehre mich dagegen, überwältigt zu werden.","I defend myself against being overwhelmed.",3],["Aus meinem Schutz wurde eine Schranke.","What was my protection has become a barrier.",3],["Ich nutze das Denken als Mauer gegen das Chaos der Welt.","I use thinking as a wall against the chaos of the world.",3],["Der Rückzug wurde zu meiner Gewohnheit und Identität.","Withdrawal has become my habit and identity.",3],["Mein Rückzug schützt mich, aber er trennt mich auch.","My withdrawal protects me, but it also separates me.",3],["Je mehr ich weiß, desto weniger spüre ich.","The more I know, the less I feel.",3],["Mein Wissen wächst, und meine Lebendigkeit nimmt ab.","My knowledge grows and my aliveness decreases.",3],["Meine Fähigkeit zu verstehen wird zum Fluch, wenn sie mich am Fühlen hindert.","My ability to understand becomes a curse when it keeps me from feeling.",3],["Mein Muster ist hochintelligent konstruiert.","My pattern is highly intelligently constructed.",2]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich habe Invasion und Verlassenwerden als Trauma erlebt.","I experienced invasion and abandonment as trauma.",3],["Mein Umfeld war zu fordernd, zu laut, zu invasiv, zu emotional oder zu unberechenbar.","My environment was too demanding, loud, invasive, emotional or unpredictable.",3],["Bezugspersonen drangen in meinen Raum ein, wenn ich Abstand brauchte.","Caregivers intruded into my space when I needed distance.",3],["Wenn ich Nähe wollte, waren sie nicht da.","When I wanted closeness, they were not there.",3],["Das Auf und Ab verwirrte mich: Wie sollte ich mit anderen umgehen?","The ups and downs confused me: how was I to deal with others?",2],["Ich habe Überflutung erlebt.","I experienced being flooded.",3],["Ich schuf mir eine innere Insel, auf der ich sicher war.","I created an inner island where I was safe.",3],["Mein Bedürfnis nach echter Verbindung habe ich immer tiefer vergraben.","I buried my need for real connection ever deeper.",3],["Ursprünglich hatte ich eine tiefe Sehnsucht nach Verbindung.","Originally I had a deep longing for connection.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Äußerlich wirke ich ruhig, analytisch und kontrolliert.","Outwardly I seem calm, analytical and controlled.",3],["Ich vernachlässige meinen Körper und meine Empfindungen.","I neglect my body and my sensations.",3],["Ich atme ruhig, mein Blick ist fokussiert, meine Grenzen sind klar.","I breathe calmly, my gaze is focused, my boundaries are clear.",2],["Mein Tonfall wird weicher, wenn ich mich öffne.","My tone softens when I open up.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["Ich spare mit Worten.","I economise with words.",3],["Ich spreche erst, nachdem ich nachgedacht habe.","I speak only after I have thought.",2],["„Ich muss das erst verstehen.“","“I first have to understand this.”",3],["Ich vermeide Gefühlsworte und beschreibe eher Beobachtungen.","I avoid words for feelings and describe observations instead.",2],["„Ich kann mich zeigen, ohne mich zu verlieren.“","“I can show myself without losing myself.”",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich möchte innere Klarheit statt Geiz leben.","I want to live inner clarity instead of avarice.",3],["Ich möchte großzügig zulassen: Kontrolle loslassen und Vertrauen zulassen.","I want to allow generously: let go of control and allow trust.",3],["Ich möchte Denken und Fühlen verbinden, ohne sie zu vermischen.","I want to connect thinking and feeling without mixing them.",3],["Ich möchte Nähe zulassen, ohne mich darin zu verlieren.","I want to allow closeness without losing myself in it.",3],["Mein Wissen wird zu Einsicht, die Einsicht zu Weisheit, und Weisheit ist Liebe, die versteht.","My knowledge becomes insight, insight becomes wisdom, and wisdom is love that understands.",3],["Mein Rückzug wird zu Sammlung, meine Distanz zu Präsenz.","My withdrawal becomes gathering, my distance becomes presence.",3],["Die Stille bleibt, aber sie wird weit.","The stillness remains, but it becomes wide.",3],["Meine gehortete Energie beginnt zu fließen.","My hoarded energy begins to flow.",3],["Ich spüre eine leise Wärme und eine Ruhe, die verbindet statt abzugrenzen.","I feel a quiet warmth and a calm that connects instead of separating.",3],["Ich erlebe Beziehung als Ausdruck von Lebendigkeit statt als Bedrohung.","I experience relationship as an expression of aliveness rather than a threat.",3]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich möchte nicht mehr verstehen, sondern erfahren.","I want not to understand more, but to experience.",3],["Ich habe eine kleine Bereitschaft, Berührung zuzulassen.","I have a small readiness to allow touch.",2],["Mein Wandel ist anfangs kaum sichtbar und darf nicht erzwungen werden.","My change is barely visible at first and must not be forced.",3]]}]}],"6":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich spüre ein leises, ständiges Hintergrundrauschen von Angst.","I feel a quiet, constant background noise of fear.",3],["Die Frage „Bin ich sicher?“ kann ich nie endgültig beantworten.","I can never finally answer the question “Am I safe?”",3],["Misstrauen gehört zu meinem Lebensgefühl.","Mistrust is part of how I feel about life.",3],["Ich spüre eine innere Bedrohung ohne klaren Anlass.","I feel an inner threat without a clear cause.",3],["Ich vertraue, aber nie ganz; ich zweifle, aber nie völlig.","I trust, but never fully; I doubt, but never completely.",3],["Ich setze auf zwei Strategien: Kontrolle und Bindung.","I rely on two strategies: control and attachment.",3],["Ich suche Halt, Orientierung und Verlässlichkeit.","I look for support, orientation and reliability.",3],["Ich bin ständig auf Empfang; meine Seele bleibt aufmerksam.","I am constantly on receive; my soul stays tuned in.",3],["Meine Angst ist wie eine Lebensversicherung für mich.","My fear is like life insurance for me.",3],["Meine Angst wird für mich zur Quelle der Sicherheit.","My fear becomes the source of safety for me.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich möchte vertrauen, statt Angst zu haben.","I want to trust instead of being afraid.",3],["Mut heißt für mich, trotz Angst gegenwärtig zu bleiben.","For me, courage means staying present despite fear.",3],["Ich vertraue bewusst, auch wenn Angst da ist.","I trust consciously, even when fear is there.",3],["Meine Angst war nicht mein Feind, sondern mein Lehrer.","My fear was not my enemy but my teacher.",3],["Ich spüre, dass das Leben mich trägt, auch wenn es unberechenbar ist.","I feel that life holds me, even when it is unpredictable.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Nur wenn ich wachsam bin, bin ich sicher.“","“Only if I am watchful am I safe.”",3],["Ich finde Vertrauen gefährlich.","I find trust dangerous.",3],["Sicherheit entsteht für mich durch Vorbereitung, nicht durch Hingabe.","For me, safety comes from preparation, not from surrender.",3],["Ich sehe überall Gefahr; Kontrolle ist meine einzige Beruhigung.","I see danger everywhere; control is my only reassurance.",3],["Ruhe erinnert mich an Wehrlosigkeit.","Calm reminds me of defencelessness.",3],["Ich frage mich ständig „Was wäre, wenn?“; wenn ich mir alles Schlimme ausmale, kann ich ihm zuvorkommen.","I keep asking “What if?”; if I imagine the worst, I can forestall it.",3],["Ich glaube, man kann Menschen nicht wirklich trauen.","I believe people cannot really be trusted.",3],["Ich weiß, dass schlimme Dinge wirklich passieren.","I know that bad things really do happen.",3],["Jeder Zwischenraum und jede Unsicherheit ist für mich ein mögliches Risiko.","Every gap and every uncertainty is a potential risk to me.",3],["Ich frage mich: Kann ich vertrauen, oder werde ich enttäuscht?","I ask myself: can I trust, or will I be disappointed?",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Wenn ich meinem Körper vertraue, entsteht Ruhe, auch wenn nicht alles sicher ist.","When I trust my body, calm arises even if not everything is safe.",1],["Wenn Regeln mein Gewissen nicht ersetzen, entsteht innere Standfestigkeit.","When rules do not replace my conscience, inner steadfastness arises.",1],["Wenn ich nicht kämpfen muss, um sicher zu sein, entstehen Mut und Vertrauen.","When I do not have to fight to be safe, courage and trust arise.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich habe eine feine Antenne für Unstimmigkeiten, wie ein sehr empfindliches Frühwarnsystem.","I have a fine antenna for inconsistencies, like a highly sensitive early-warning system.",3],["Ich bereite mich auf Gefahren vor, bevor sie eintreten.","I prepare for dangers before they occur.",3],["Ich denke, plane, überprüfe und sichere ab.","I think, plan, check and secure.",3],["Ich rationalisiere, intellektualisiere und analysiere meine Angst.","I rationalise, intellectualise and analyse my fear.",3],["Ich denke über meine Angst nach, statt sie zu fühlen.","I think about my fear instead of feeling it.",3],["Ich beobachte Menschen auf versteckte Absichten hin.","I watch people for hidden intentions.",3],["Ich male mir Katastrophen aus.","I imagine catastrophes.",3],["Ich hinterfrage kritisch und recherchiere gründlich.","I question critically and research thoroughly.",3],["Ich misstraue oberflächlichem Wissen.","I distrust superficial knowledge.",2],["Ich mache Pläne für verschiedene Eventualitäten.","I make plans for various contingencies.",3],["Ich verwechsle Anspannung mit Lebendigkeit.","I mistake tension for aliveness.",3]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich zögere.","I hesitate.",3],["Ich zweifle hartnäckig an mir selbst und an anderen.","I doubt myself and others persistently.",3],["Ich suche Halt bei Autoritäten, Strukturen und Menschen, die „wissen, was richtig ist“.","I seek support in authorities, structures and people who “know what is right”.",3],["Sobald ich mich gebunden habe, nagt das Misstrauen an mir.","As soon as I have committed, mistrust gnaws at me.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich habe diffuse Ängste und innere Anspannung.","I have diffuse fears and inner tension.",3],["Ich habe das Gefühl einer ungreifbaren Bedrohung.","I have a feeling of elusive threat.",3],["Ich bin in chronischer Alarmbereitschaft.","I am in a state of chronic alert.",3],["Mein Körper ist angespannt, mein Geist im Daueralarm, meine Gefühle in latenter Erregung.","My body is tense, my mind on constant alarm, my emotions in latent arousal.",3],["Oft weiß ich gar nicht, dass ich Angst habe, weil Wachsamkeit für mich der Normalzustand ist.","I often do not know I am afraid, because watchfulness feels normal to me.",3],["Ruhe fühlt sich für mich bedrohlich an.","Calm feels threatening to me.",3],["Meine innere Alarmanlage lässt sich nicht abstellen.","I cannot switch off my inner alarm.",3],["Für mich bedeutet Bindung Kontrollverlust.","For me, attachment means loss of control.",3],["Ich bin hin- und hergerissen zwischen Vertrauen und Misstrauen, Nähe und Rückzug.","I am torn between trust and mistrust, closeness and withdrawal.",3],["Ich mache mir Sorgen, fühle mich übermäßig verantwortlich und bin übertrieben vorsichtig.","I worry, feel excessively responsible and am overly cautious.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Meinen Ärger zeige ich oft durch Angst und Misstrauen.","I often show my anger through fear and mistrust.",3],["Ich kann intensiv und konfrontativ werden, wenn ich mich bedroht fühle.","I can become intense and confrontational when I feel threatened.",3],["Mein Zorn zeigt sich als Sorgen, Skepsis, Unsicherheit und ständige Wachsamkeit.","My anger shows up as worries, scepticism, insecurity and constant watchfulness.",3],["Ich greife manchmal an, um Angreifer einzuschüchtern.","Sometimes I counterattack to intimidate attackers.",2]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich sichere ab, überprüfe und bereite vor.","I secure, check and prepare.",3],["Ich bin loyal, verantwortungsbewusst, vorsichtig und treu.","I am loyal, responsible, cautious and faithful.",3],["Ich baue starke Bindungen zu vertrauenswürdigen Menschen auf.","I build strong bonds with trustworthy people.",3],["Ich habe Freude an Gruppenevents, Wanderungen und Mannschaftssport, wo man sich auf andere verlassen kann.","I enjoy group events, hiking and team sports where I can rely on others.",2],["Ich halte mich an Regeln, Strukturen und Systeme.","I stick to rules, structures and systems.",3],["Ich setze mich unermüdlich für stabile Strukturen ein.","I commit myself tirelessly to stable structures.",2],["Ich suche Menschen, Institutionen und Systeme, die Halt versprechen.","I look for people, institutions and systems that promise support.",3]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich suche Nähe, traue ihr aber nicht; ich brauche Führung, misstraue ihr aber.","I seek closeness but do not trust it; I need guidance but mistrust it.",3],["Ich habe ein Bedürfnis nach Sicherheit und zugleich Angst vor Abhängigkeit.","I have a need for safety and, at the same time, a fear of dependence.",3],["Ich zeige Liebe durch Treue, Zuverlässigkeit und emotionale Unterstützung.","I show love through faithfulness, reliability and emotional support.",3],["In der Partnerschaft brauche ich Vertrauen, Sicherheit und Geborgenheit.","In a partnership I need trust, safety and security.",3],["Ich prüfe Nähe und Verlässlichkeit.","I test closeness and reliability.",2],["Ich suche Schutz und Absicherung durch Wärme und Liebenswürdigkeit.","I seek protection and security through warmth and amiability.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich gewinne Einfluss durch Gruppen, Bündnisse und Loyalität.","I gain influence through groups, alliances and loyalty.",2],["Pflicht und Verantwortungsbewusstsein sind meine Basis.","Duty and a sense of responsibility are my foundation.",3],["Zu meinen Stärken gehören Zuverlässigkeit, Loyalität und Zusammenarbeit.","My strengths include reliability, loyalty and cooperation.",2],["Zu meinen Schwächen gehören Ängstlichkeit und Zögern.","My weaknesses include anxiety and hesitation.",3],["Ich halte mich exakt an Regeln und ordne mich Autoritäten unter.","I follow rules exactly and subordinate myself to authorities.",2]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Auf Angst reagiere ich automatisch mit Flucht oder Kontrolle.","I answer fear automatically with flight or control.",3],["Wenn meine Angst nachlässt, werde ich unsicher.","When my fear subsides, I become insecure.",3],["Ich bin ständig angespannt, auch in Ruhe.","I am constantly tense, even at rest.",3],["Ich kämpfe, um mich sicher zu fühlen.","I fight to feel safe.",2]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Kontrolle ist für mich Ausgleich, Loyalität meine Lebensstrategie.","Control is how I compensate, and loyalty is my life strategy.",3],["Meine Angst ist Teil von mir selbst.","My fear is part of who I am.",3],["Bei mir wechseln sich Misstrauen und Abhängigkeit ab.","Mistrust and dependence alternate in me.",3],["Was mich einst schützte, ist heute eine Last.","What once protected me is now a burden.",3],["Mein Denken übernimmt alles, was als Schutz gedacht war.","My thinking takes over everything that was meant as protection.",3],["Meine Angst zeigt sich verkleidet: als Sorge, Misstrauen, Verantwortungsgefühl, Vorsicht oder Zweifel.","My fear comes disguised: as worry, mistrust, a sense of responsibility, caution or doubt.",3],["Ich sehe die Gefahr eher draußen als in mir.","I see the danger outside rather than within me.",2]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich trage das Trauma einer Bedrohung und des verlorenen Urvertrauens in mir.","I carry the trauma of a threat and of lost basic trust.",3],["Mein Umfeld war instabil, widersprüchlich oder unzuverlässig.","My environment was unstable, contradictory or unreliable.",3],["Ein Elternteil von mir war unberechenbar, seine Stimmung wechselhaft.","One of my parents was unpredictable, and their mood changeable.",3],["Meine Mutter vergaß einmal, mich abzuholen.","My mother once forgot to pick me up.",2],["Ich habe einen erschreckenden Film gesehen, in dem Menschen starben.","I saw a frightening film in which people died.",1],["Ich habe gelernt, kleinste Veränderungen wahrzunehmen, um Gefahren früh zu erkennen.","I learned to notice the smallest changes in order to recognise dangers early.",3],["Ursprünglich war ich lebendig, neugierig und unbeschwert.","Originally I was lively, curious and carefree.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Mein Körper lebt in ständiger leichter Spannung.","My body lives in constant slight tension.",3],["Mein Nervensystem reagiert auf jede Veränderung und jeden Windhauch.","My nervous system reacts to every change and every breath of wind.",3],["Ich möchte mein vegetatives Nervensystem beruhigen.","I want to calm my autonomic nervous system.",2],["Ich wünsche mir einen wachen Blick und einen ruhigen Körper.","I wish for a watchful gaze and a calm body.",1]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["„Was ist, wenn …?“","“What if …?”",3],["„Bin ich sicher?“","“Am I safe?”",3],["Ich stelle Fragen und hinterfrage kritisch.","I ask questions and question critically.",3],["Ich spreche meine Sorgen und Loyalitäten offen aus.","I speak my worries and loyalties openly.",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich möchte Vertrauen als Tugend leben: seelische Stabilität unabhängig von äußeren Umständen.","I want to live trust as a virtue: inner stability independent of external circumstances.",3],["Ich möchte mutig sein: ohne Beweis vertrauen, ohne Gewissheit handeln, ohne Kontrolle leben.","I want to be courageous: to trust without proof, to act without certainty, to live without control.",3],["Ich wünsche mir ein reifes, wissendes, stilles Vertrauen, das nicht naiv ist.","I wish for a mature, knowing, quiet trust that is not naive.",3],["Ich wünsche mir die Freiheit, mich dem Unbekannten anzuvertrauen.","I wish for the freedom to entrust myself to the unknown.",3],["Ich möchte meine Angst nicht bekämpfen müssen, um sie zu überwinden.","I would like not to have to fight my fear in order to overcome it.",3],["Ich möchte Raum für Unsicherheit öffnen, statt Sicherheit zu schaffen.","I want to open space for uncertainty rather than create safety.",3],["Ich wünsche mir eine Pause zwischen Reiz und Reaktion.","I wish for a pause between stimulus and reaction.",3],["Ich möchte meine Angst beobachten, ohne sie zu bewerten.","I want to observe my fear without judging it.",3],["Ich möchte meine eigene Standfestigkeit finden, statt Autorität im Außen zu suchen.","I want to find my own steadfastness instead of looking for authority outside.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich wünsche mir eine körperlich spürbare Sicherheit, die aus Empfindung entsteht, nicht aus Argumenten.","I wish for a physically perceptible safety that arises from sensation, not from arguments.",3],["Ich möchte loslassen und erfahren, dass nichts geschieht.","I want to let go and experience that nothing happens.",2],["Situationen, die früher bei mir Alarm auslösten, erlebe ich ruhiger.","I experience situations that used to trigger alarm in me more calmly.",2]]}]}],"7":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich fliehe vor dem Schmerz.","I flee from pain.",3],["Ich strebe unersättlich nach dem Guten, dem Nächsten, dem Mehr.","I strive insatiably for the good, the next, the more.",3],["Ich habe tiefe Angst vor innerer Leere.","I have a deep fear of inner emptiness.",3],["Ich verwandle Schmerz in Aktivität, Einsamkeit in Geselligkeit, Trauer in Witz.","I turn pain into activity, loneliness into sociability, grief into wit.",3],["Mein Leben bleibt bunt, solange ich die Schatten meide.","My life stays colourful as long as I avoid the shadows.",3],["Ich überspiele den Schmerz mit Ersatzlust, statt ihn zu fühlen.","I cover up pain with substitute pleasure instead of feeling it.",3],["Ich bleibe in Bewegung, um mich zu schützen.","I keep moving to protect myself.",3],["Stillstand fühlt sich für mich an wie Tod.","Standing still feels like death to me.",3],["Ich will mich nicht festlegen, denn in der Stille wartet der Schmerz.","I don't want to commit, because pain is waiting in stillness.",3],["Ich schaffe mir Optionen, um Schmerz zu vermeiden.","I create options for myself to avoid pain.",3],["Mich treibt die Furcht, stehen zu bleiben.","I am driven by the fear of standing still.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich wünsche mir wahre Freude statt Flucht.","I long for true joy instead of flight.",3],["Wahre Freude entsteht bei mir, wenn ich aufhöre zu fliehen.","True joy arises in me when I stop fleeing.",3],["Freude ist für mich kein Ziel, sondern ein Zustand des Daseins.","For me, joy is not a goal but a state of being.",3],["Ich erlebe, dass Schmerz nicht zerstört, sondern verbindet.","I experience that pain does not destroy but connects.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Wenn ich den Schmerz meide, bleibt das Leben leicht.“","“If I avoid pain, life stays light.”",3],["Ich finde, es muss alles gut werden, das Gegenteil wäre unerträglich.","I feel everything must turn out well; the opposite would be unbearable.",3],["Ich sehe Schmerz als Fehler, der vermieden werden muss.","I see pain as a mistake that must be avoided.",3],["Leichtigkeit ist für mich ein Überlebensprinzip.","Lightness is a survival principle for me.",3],["Für mich gibt es entweder Freude oder Schmerz; beides zugleich ist mir fremd.","For me it is either joy or pain; both at once is alien to me.",3],["Jede Begrenzung weckt in mir alte Ängste, jedes Ende klingt nach Verlust.","Every limit awakens old fears in me, every ending sounds like loss.",3],["Solange ich den Schmerz vermeide, ist alles in Ordnung.","As long as I avoid pain, everything is fine.",2],["Als Kind war der Schmerz für mich überfordernd und meine Umgebung zu schwer.","As a child, pain overwhelmed me and my environment was too heavy.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Wenn ich genug habe, ohne mehr zu brauchen, entsteht wirklicher Genuss.","When I have enough without needing more, real enjoyment arises.",1],["Wenn ich nicht gut sein muss, wird meine Freude ehrlich, frei und nahbar.","When I don't have to be good, my joy becomes honest, free and approachable.",1],["Wenn ich Tiefe zulasse, statt das Besondere zu jagen, entsteht echte Erfüllung.","When I allow depth instead of chasing the special, real fulfilment arises.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich lenke meine Aufmerksamkeit auf Schönes oder Aufregendes, sobald Schmerz droht.","I turn my attention to something beautiful or exciting as soon as pain looms.",3],["Ich denke schon an Neues, bevor der Verlust ankommt.","I think of new things before the loss arrives.",3],["Ich denke schnell, kreativ und lösungsorientiert.","I think quickly, creatively and in a solution-oriented way.",3],["Wo andere verzweifeln, finde ich eine Idee.","Where others despair, I find an idea.",3],["Ich ziehe mich in meine Vorstellungswelt zurück.","I retreat into an imaginary world.",3],["Ich sammle breites, vielfältiges Wissen und springe zwischen Themen.","I collect broad, varied knowledge and jump between topics.",3],["Neugier und Begeisterung treiben mein Lernen an.","Curiosity and enthusiasm drive my learning.",2],["Ich deute Unangenehmes um.","I reinterpret the unpleasant.",3],["Alles Dunkle verdränge oder deute ich um.","I repress or reinterpret everything dark.",3],["Ich sehe die Welt durch eine farbenfrohe Fantasiebrille und liebe utopische Projekte.","I see the world through colourful fantasy glasses and love utopian projects.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich halte mir Optionen offen und treffe spontane Entscheidungen.","I keep my options open and make spontaneous decisions.",3],["Ich halte Projekte, Beziehungen und Gedanken in Bewegung.","I keep projects, relationships and thoughts in motion.",3],["Ich suche ständig neue Erfahrungen, Ideen und Möglichkeiten.","I constantly seek new experiences, ideas and possibilities.",3],["Ich will mich nicht festlegen.","I don't want to commit.",3],["Ich bin impulsiv und lasse mich leicht ablenken.","I am impulsive and easily distracted.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich bin rastlos.","I am restless.",3],["Ich fürchte, stehen zu bleiben.","I fear stopping.",3],["Ich habe Angst, innere Unruhe oder Dunkelheit zu spüren.","I am afraid of feeling inner unrest or darkness.",3],["Ich spüre innere Spannung und Unruhe.","I feel inner tension and unrest.",3],["Hinter meiner Dauerheiterkeit liegt Entfremdung.","Behind my constant cheerfulness lies alienation.",3],["In mir ist eine Spaltung: Mein äußeres Selbst ist lebendig, mein inneres still und abgeschnitten.","There is a split in me: my outer self is lively, my inner self quiet and cut off.",3],["Ich erlebe Erschöpfung, Sinnverlust und eine subtile innere Leere.","I experience exhaustion, loss of meaning and a subtle inner emptiness.",3],["Ich rede über alles und fühle wenig.","I talk about everything and feel little.",3],["Meine Worte sind klüger als mein Erleben.","My words are cleverer than my experience.",3],["Ich lasse Trauer, Melancholie und Ohnmacht nicht zu.","I don't allow grief, melancholy or powerlessness.",3],["Mein Glück ist manchmal nur ein Schutz vor dem Fühlen.","My happiness is sometimes just a protection against feeling.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich vermeide unangenehme Gefühle und lenke mich ab.","I avoid unpleasant feelings and distract myself.",3],["Wenn man mich direkt konfrontiert, kann mein Zorn explosiv und unvorhersehbar sein.","When I am confronted directly, my anger can be explosive and unpredictable.",2],["Ich lenke schnell von negativen Emotionen wie Zorn ab.","I quickly distract myself from negative emotions such as anger.",3],["Wenn ein Thema an Schmerz grenzt, wechsle ich elegant das Thema oder mache einen Scherz.","When a topic borders on pain, I elegantly change the subject or make a joke.",3]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich bin charmant, vital und inspirierend, eine Quelle von Ideen und Begeisterung.","I am charming, vital and inspiring, a source of ideas and enthusiasm.",3],["Ich suche Abenteuer und Abwechslung, spontane und aufregende Aktivitäten.","I seek adventure and variety, spontaneous and exciting activities.",3],["Ich liebe Reisen, Extremsportarten, Feste und neue Erfahrungen.","I love travel, extreme sports, parties and new experiences.",2],["Ich probiere immer Neues aus.","I always try new things.",3],["Humor und Leichtigkeit schützen mich.","Humour and lightness protect me.",3],["Ich sehe das Leben als Bühne, auf der das Leichte und Bunte Vorrang hat.","I see life as a stage where the light and colourful take precedence.",3],["Ich manage meine guten Gefühle ständig im Inneren.","I constantly manage my good feelings inside.",3],["Ich zerstreue mich.","I distract myself.",3]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich zeige Liebe durch Abenteuer, Spontaneität und positive Erlebnisse.","I show love through adventure, spontaneity and positive experiences.",2],["Ich brauche Spaß, Freiheit und das Gefühl, lebendig und inspiriert zu sein.","I need fun, freedom and the feeling of being alive and inspired.",3],["Ich halte Nähe aus sicherer Leichtigkeit heraus und meide die Tiefe der Gefühle und damit die Liebe.","I keep closeness light and avoid the depth of feelings and thus love.",3],["Ich pflege pragmatische Vorteilsnetzwerke.","I maintain pragmatic networks of advantage.",2],["Ich bin ein opferbereiter Idealist und leide unbewusst am Verzicht.","I am a self-sacrificing idealist and unconsciously suffer from renunciation.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich gewinne Einfluss durch Begeisterung, Überzeugung und Netzwerke.","I gain influence through enthusiasm, conviction and networks.",3],["Ich motiviere andere durch Energie, Ideen und Optimismus.","I motivate others through energy, ideas and optimism.",3],["Ich reiße andere mit Visionen und positiver Energie mit.","I carry others along with visions and positive energy.",3],["Meine Stärken sind Enthusiasmus, Vielseitigkeit und kreative Fantasie.","My strengths are enthusiasm, versatility and creative imagination.",2],["Meine Schwächen sind Impulsivität, Ablenkbarkeit und das Vermeiden von Unannehmlichkeiten.","My weaknesses are impulsiveness, distractibility and avoiding unpleasantness.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Ich wechsle das Thema, relativiere und mache einen Scherz.","I change the subject, play things down and make a joke.",3],["Ich verbinde Schmerz automatisch mit Gefahr.","I automatically associate pain with danger.",3],["Was ich verdränge, baut Druck in mir auf.","What I repress builds up pressure in me.",3],["Bei Begrenzung werde ich unruhig.","I become restless when I am limited.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich ersetze Angst, Trauer und Ohnmacht durch Freude, Aktivität und Kontrolle.","I replace fear, grief and powerlessness with joy, activity and control.",3],["Ich verwandle verdrängten Schmerz in etwas anderes.","I transform repressed pain into something else.",3],["Ich flüchte in das Gegenteil dessen, was ich erlebe.","I flee into the opposite of what I experience.",3],["Ich teile Schmerz in kleine, kontrollierbare Portionen auf.","I divide pain into small, controllable portions.",3],["Ich nutze Positivität als Abwehr.","I use positivity as a defence.",3],["Mit Überfülle überspiele ich die Angst vor Leere.","I cover up my fear of emptiness with overabundance.",3],["Ich maskiere die Energie des Schmerzes, statt sie zu integrieren.","I mask the energy of pain instead of integrating it.",3],["Das Licht blendet mich.","The light dazzles me.",3]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich trage das Trauma des vermiedenen Schmerzes und des verlorenen Tiefgangs in mir.","I carry the trauma of avoided pain and lost depth.",3],["Ich habe Kälte, Unberechenbarkeit, Verlust oder emotionale Abwesenheit erlebt.","I experienced coldness, unpredictability, loss or emotional absence.",3],["Ich wurde mit dem Schmerz allein gelassen: Mein Vater war gereizt, meine Mutter hatte keine Zeit.","I was left alone with pain: my father was irritated, my mother had no time.",3],["Ich lernte, dass es leichter ist, das Dunkle zu ignorieren, als es zu durchleben.","I learned that it is easier to ignore the dark than to live through it.",3],["Ich verlegte den Schwerpunkt auf die hellen Seiten: Fantasie, Freude, Ablenkung, Begeisterung.","I shifted my centre of gravity to the bright sides: fantasy, joy, distraction, enthusiasm.",3],["Ich wurde sehr gut darin, mich selbst abzulenken.","I became very good at distracting myself.",3],["Ursprünglich hatte ich echte Neugier und natürliches Staunen.","Originally I had real curiosity and natural wonder.",2],["Meine Umgebung war emotional wechselhaft oder zu schwer.","My environment was emotionally changeable or too heavy.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Ich bin beweglich, unruhig und schnell.","I am agile, restless and quick.",3],["Ich lächle, um mich zu schützen.","I smile to protect myself.",3],["Meine Energie ist immer in Bewegung, nie ganz still.","My energy is always in motion, never entirely still.",3],["Zuerst kommt die Stille, dann die Verbundenheit mit meinem Körper und dem gegenwärtigen Moment.","First comes stillness, then connection with my body and the present moment.",2],["Ich bin lebendig, magnetisch, sinnlich und abenteuerlustig.","I am lively, magnetic, sensual and adventurous.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["Ich nehme Witz und Scherz statt Trauer.","I choose wit and jokes instead of grief.",3],["Ich bin redegewandt und mitreißend.","I am eloquent and rousing.",2],["Ich reflektiere klug über alles, ohne zu fühlen.","I reflect cleverly on everything without feeling.",3],["Ich spreche in Möglichkeiten, Plänen und Ideen.","I speak in possibilities, plans and ideas.",3],["„Das wird schon.“ / „Alles halb so schlimm.“","“It will be fine.” / “It’s not that bad.”",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich höre auf, mich selbst zu überholen, und Stille entsteht.","I stop overtaking myself, and stillness arises.",3],["Ich habe den Mut, in der Stille zu bleiben und dem zu begegnen, was ich vermieden habe.","I have the courage to stay in stillness and meet what I avoided.",3],["Aus dem Gefürchteten entsteht Frieden.","From what I feared, peace arises.",3],["Meine Freude ist still, tief und warm.","My joy is quiet, deep and warm.",3],["Meine Freude hängt nicht davon ab, dass etwas geschieht, sondern dass ich etwas loslasse.","My joy does not depend on something happening but on my letting something go.",3],["Mein Lachen wird nicht seltener, aber wahrhaftiger.","My laughter does not become rarer but more truthful.",3],["Ich erlebe innere Freiheit und Frieden mit allen Gefühlen.","I experience inner freedom and peace with all feelings.",3],["Ich wähle Tiefe statt Zerstreuung.","I choose depth instead of distraction.",2],["Ich wähle Ehrlichkeit statt Fassade.","I choose honesty instead of facade.",3]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Ich brauche eine Atmosphäre von Sicherheit und Sanftheit, in der Fühlen wieder möglich wird.","I need an atmosphere of safety and gentleness in which feeling becomes possible again.",3],["Ich brauche keine Konfrontation, sondern Erlaubnis.","I need not confrontation but permission.",3],["Ich genieße Möglichkeiten, ohne dem gegenwärtigen Moment auszuweichen.","I enjoy possibilities without evading the present moment.",2]]}]}],"8":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich spüre eine intensive Lebenskraft, nicht im erotischen Sinn.","I feel an intense life force, not in the erotic sense.",3],["Ich habe Angst vor Ohnmacht.","I am afraid of powerlessness.",3],["Mir sind Macht, Energie und Unmittelbarkeit wichtig.","Power, energy and immediacy matter to me.",3],["Ich ergreife das Leben, statt es zu denken.","I seize life rather than think about it.",3],["Ich will nicht Opfer sein, sondern Ursache.","I don't want to be a victim but a cause.",3],["Stärke schützt mich, Macht ist meine Überlebensstrategie.","Strength protects me, and power is my survival strategy.",3],["Ich gleiche meine Angst vor Abhängigkeit aus.","I compensate for my fear of dependence.",3],["Ich verwechsle Härte mit Stärke.","I confuse hardness with strength.",3],["Kontrolle bewahrt mich vor Schmerz.","Control keeps me from pain.",3],["Ich lenke mein Leben mehr, als ich es erlebe.","I steer my life more than I experience it.",3],["Meine Kraft muss sich ständig selbst bestätigen.","My strength constantly has to confirm itself.",3],["Für mich ist das Leben ein Kampf: Sieger oder Besiegter.","For me life is a fight: victor or vanquished.",3]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich wünsche mir Kraft statt Kontrolle.","I want strength instead of control.",3],["Ich möchte von Kontrolle zu Autorität kommen.","I want to move from control to authority.",3],["Meine Kontrolle entsteht aus Angst, Autorität entsteht aus Vertrauen.","My control arises from fear; authority arises from trust.",3],["Ich wünsche mir Unschuld statt Macht.","I want innocence instead of power.",3],["Ich möchte, dass aus Macht Präsenz wird, aus Kontrolle Vertrauen und aus Härte stille Kraft.","I want power to become presence, control to become trust, and hardness to become quiet strength.",3]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Nur wenn ich stark bin, bin ich sicher.“","“Only if I am strong am I safe.”",3],["Ich glaube: Nur wer stark ist, überlebt.","I believe only the strong survive.",3],["Ich halte Verletzlichkeit für gefährlich.","I find vulnerability dangerous.",3],["Ich halte Offenheit für gefährlich; nur Stärke gibt mir Sicherheit.","I find openness dangerous; only strength gives me safety.",3],["„Ich muss auf mich selbst aufpassen. Niemand kommt.“","“I have to look after myself. Nobody comes.”",3],["Ich finde, nur wer stark ist, verdient Vertrauen.","I feel only the strong deserve trust.",3],["Klein, schwach oder abhängig zu sein, ist für mich gefährlich.","Being small, weak or dependent feels dangerous to me.",3],["Was ich nicht kontrollieren kann, bedroht mich.","What I cannot control threatens me.",3],["Selbst Zärtlichkeit kann mir Angst machen, weil sie Kontrollverlust bedeutet.","Even tenderness can frighten me because it means loss of control.",3],["Unschuld fühlt sich für mich gefährlich an.","Innocence feels dangerous to me.",3]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Wenn ich Kontrolle loslasse, bleibt meine Kraft lebendig und ohne Härte.","When I let go of control, my strength stays alive and without hardness.",1],["Wenn mein Schutz nicht zu Besitz wird, entsteht starke, gerechte Führung.","When my protection does not become possession, strong, just leadership arises.",1],["Wenn ich Intensität nicht mit Kampf verwechsle, entsteht Nähe ohne Machtprobe.","When I do not confuse intensity with fighting, closeness without a power test arises.",1]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Ich sehe die Welt als Feld, das ich behaupten und gestalten muss.","I see the world as a field I must assert and shape.",3],["Ich erkenne sehr genau, ob jemand authentisch ist; Unechtheit und psychologische Tricks spüre ich sofort.","I recognise very precisely whether someone is authentic; I sense inauthenticity and psychological tricks immediately.",3],["Ich teste, ob mein Gegenüber standhält.","I test whether the other person holds firm.",3],["Ich will Ergebnisse, keine Prozesse.","I want results, not processes.",3],["Ich bevorzuge praktisches Wissen und setze es sofort in die Tat um.","I prefer practical knowledge and put it into action at once.",3],["Ich entscheide, statt zu analysieren.","I decide rather than analyse.",3],["Ich vertraue meiner Kraft mehr als meiner Sensibilität.","I trust my strength more than my sensitivity.",3],["Ich halte den Ausgang unter Kontrolle: über mich, andere und die Situation.","I keep outcomes under control: over myself, others and the situation.",3]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich bin im Bereich der Willensenergie festgelegt.","I am fixated in the area of will energy.",3],["Ich gehe in die aktive Opposition.","I go into active opposition.",3],["Ich ersetze Angst durch Tat, Ohnmacht durch Initiative, Hilflosigkeit durch Angriff.","I replace fear with action, powerlessness with initiative, helplessness with attack.",3],["Ich setze mich durch und schütze die Schwachen.","I assert myself and protect the weak.",3],["Ich kann nicht mehr aufhören, stark zu sein.","I can no longer stop being strong.",3]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich fliehe vor dem Gefühl, ausgeliefert zu sein.","I flee from the feeling of being at someone's mercy.",3],["Hinter meiner Stärke liegt eine Verletzlichkeit, die gut verborgen ist, auch vor mir selbst.","Behind my strength lies a vulnerability that is well hidden, even from myself.",3],["Hinter der Maske der Stärke spüre ich leise Einsamkeit und verborgene Traurigkeit.","Behind the mask of strength I feel quiet loneliness and hidden sadness.",3],["Mein weiches, empfindsames Selbst ist abgespalten.","My soft, sensitive self is split off.",3],["Ich habe ein großes, warmes, großzügiges, leidenschaftliches Herz, das ich früh als gefährlich erlebt habe.","I have a large, warm, generous, passionate heart that I experienced early on as dangerous.",3],["Ich stehe in ständiger Anspannung, um mich zu behaupten.","I am in constant tension in order to assert myself.",3],["Ohne Bewegung fühle ich mich unsicher.","Without movement I feel insecure.",3],["Wut war mein Werkzeug: Sie ließ mich größer wirken, als ich war.","Anger was my tool: it made me look bigger than I was.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["Ich drücke Ärger direkt und unerschrocken aus und habe keine Angst vor Konfrontation.","I express anger directly and fearlessly, and I am not afraid of confrontation.",3],["Mein Zorn kann sehr intensiv und kontrollierend sein.","My anger can be very intense and controlling.",3],["Ich trete kraftvoll und konfrontativ auf, wenn ich mich unrecht behandelt fühle.","I come across powerfully and confrontationally when I feel treated unjustly.",3],["Auf Verletzung reagiere ich mit Kontrolle, auf Unsicherheit mit Dominanz.","I react to injury with control, and to uncertainty with dominance.",3]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich habe enorme Durchsetzungskraft: Ich kann führen, entscheiden, tragen und Verantwortung übernehmen.","I have enormous drive: I can lead, decide, carry and take responsibility.",3],["Meine Energie ist unmittelbar und magnetisch.","My energy is immediate and magnetic.",3],["Wo andere sich zurückziehen, gehe ich nach vorn.","Where others withdraw, I go forward.",3],["Ich kontrolliere Risiken, zeige Stärke und Durchsetzungsvermögen und biete Schutz.","I control risks, show strength and assertiveness, and offer protection.",3],["Ich habe Freude an Sport, Wettbewerben, Herausforderungen, Natur und Projekten mit Einfluss.","I enjoy sport, competitions, challenges, nature and projects with influence.",2],["Ich sichere mein Territorium spontan und kompromisslos.","I secure my own territory spontaneously and uncompromisingly.",2]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich zeige Liebe durch Schutz, Unterstützung und Übernahme von Verantwortung.","I show love through protection, support and taking responsibility.",3],["In der Partnerschaft brauche ich Respekt, Autonomie und das Gefühl, stark zu sein.","In a partnership I need respect, autonomy and the feeling of being strong.",3],["Ich halte die Welt auf Distanz, indem ich sie bestimme.","I keep the world at a distance by determining it.",3],["Meine Härte schützt mich vor Schmerz, verhindert aber Nähe.","My hardness protects me from pain but prevents closeness.",3],["Ich will meinen Partner besitzen und überschreite kompromisslos Grenzen.","I want to possess my partner and I cross boundaries uncompromisingly.",2],["Ich beschütze die Schwachen gegen Ungerechtigkeit.","I protect the weak against injustice.",2]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich nehme direkt Kontrolle und Einfluss durch Autorität und Durchsetzungsstärke.","I take direct control and influence through authority and assertiveness.",3],["Ich übe Macht offen aus und fordere sie ein.","I exercise power openly and demand it.",3],["Meine Stärken sind Durchsetzungsfähigkeit, Unabhängigkeit und Führungsstärke.","My strengths are assertiveness, independence and leadership.",3],["Meine Schwächen sind Dominanz, Unnachgiebigkeit und die Überbewertung meiner eigenen Stärke.","My weaknesses are dominance, inflexibility and overvaluing my own strength.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Meine Stärke kippt in Härte, meine Entschlossenheit in Starrheit.","My strength tips into hardness, my determination into rigidity.",3],["Beides führt mich in die Sackgasse: mich einschüchtern lassen oder brechen wollen.","Both lead me into a dead end: being intimidated or trying to break.",2],["Ich ziehe mich zurück, wenn jemand unecht ist oder Tricks anwendet.","I withdraw when someone is inauthentic or uses tricks.",3],["Meine Willenskräfte sind überhitzt.","My will forces are overheated.",3]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich habe ein Abwehrsystem gegen Ohnmacht.","I have a defence system against powerlessness.",3],["Ich wehre mich überkompensierend: Mein aktiver Pol ist überhöht, mein verletzlicher Pol unterdrückt.","I defend myself by overcompensating: my active pole is exaggerated, my vulnerable pole suppressed.",3],["In mir ist unbewusst etwas gespalten: Der weiche Teil wird durch den Willen ersetzt.","Something in me is unconsciously split: the soft part is replaced by will.",3],["Meine Härte ist wie Rüstung und Panzer: nicht sichtbar, aber spürbar.","My hardness is like armour and a shell: not visible but tangible.",3],["Ich ersetze Empfindsamkeit durch Entschlossenheit, Offenheit durch Kontrolle, Verletzlichkeit durch Dominanz.","I replace sensitivity with determination, openness with control, vulnerability with dominance.",3],["Ich trage die Maske der Stärke so lange, dass ich vergessen habe, was darunter ist.","I have worn the mask of strength so long that I have forgotten what is underneath.",3],["Meine Energie bleibt in der oberen Hälfte gebunden: im Willen, Denken und Handeln.","My energy stays bound in the upper half: in will, thinking and action.",2]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Ich war ein ungeschütztes Kind, das zu schnell stark werden musste.","I was an unprotected child who had to become strong too fast.",3],["Niemand war da, wenn ich Schutz brauchte.","Nobody was there when I needed protection.",3],["Wenn ältere Kinder mich verletzten, sah keiner hin.","When older children hurt me, nobody looked.",3],["Ich habe Kontrollverlust, Übergriffe, Instabilität oder emotionale Unsicherheit erlebt.","I experienced loss of control, assaults, instability or emotional insecurity.",3],["Ich habe emotionale Kälte, willkürliche Autorität, enttäuschtes Vertrauen und bestrafte Schwäche erlebt.","I experienced emotional coldness, arbitrary authority, disappointed trust and punished weakness.",3],["Ich habe meine natürliche Energie zur Kraft weiterentwickelt.","I developed my natural energy into strength.",3],["Mit der Zeit bin ich verhärtet und habe den Zugang zu meiner ursprünglichen Weichheit verloren.","Over time I hardened and lost access to my original softness.",3],["Ursprünglich war ich sensibel, neugierig, voller Energie, offen, unschuldig und verletzlich.","Originally I was sensitive, curious, full of energy, open, innocent and vulnerable.",2]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Mein Körper steht ständig unter Strom.","My body is constantly under current, in tension.",3],["Meine Energie ist präsent und direkt, und sie prüft auch.","My energy is present and direct, and it also tests.",3],["Ich wirke magnetisch, intensiv, souverän und kraftvoll.","I come across as magnetic, intense, sovereign and powerful.",2],["Meine überhitzten Willenskräfte brauchen Erdung, das ist meine Entwicklungsrichtung.","My overheated will forces need grounding; that is my direction of development.",2],["Ich möchte spüren, dass ich loslassen kann, ohne zu fallen.","I want to feel that I can let go without falling.",3]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["Ich bin direkt und klar, ohne Umschweife.","I am direct and clear, without detours.",3],["Ich entscheide, statt zu fragen: „So machen wir das.“","I decide instead of asking: “This is how we do it.”",3],["Ich spreche prüfend und herausfordernd.","I speak in a testing, challenging way.",2],["„Ich brauche niemanden.“","“I don’t need anyone.”",3],["Ich spreche die Wahrheit unverblümt aus.","I speak the truth bluntly.",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Unschuld bedeutet für mich Reinheit der Kraft, nicht Naivität.","To me innocence means purity of strength, not naivety.",3],["Ich wünsche mir Würde als Haltung der reifen Acht: Bewusstsein der Kraft, getragen von Liebe und Respekt.","I want dignity as the attitude of the mature Eight: awareness of strength, carried by love and respect.",3],["Ich möchte aufhören, mich zu verteidigen.","I want to stop defending myself.",3],["Ich möchte auch im Nicht-Tun sicher sein.","I want to feel safe even in not-doing.",3],["Ich möchte meine seelische Verletzlichkeit zulassen.","I want to allow my vulnerability.",3],["Ich wünsche mir Kraft in Milde und Führung durch Präsenz.","I want strength in gentleness and leadership through presence.",3],["Mein Herz braucht keine Masken mehr, weil es nichts beweisen muss.","My heart needs no masks anymore because it has nothing to prove.",3],["Ich wünsche mir Beziehung auf Augenhöhe: ruhig, klar, ohne Machtspiel.","I want relationship at eye level: calm, clear, without power games.",3],["Ich möchte Verantwortung und Führung übernehmen, ohne andere kontrollieren zu müssen.","I want to take responsibility and leadership without having to control others.",2],["Ich möchte Stärke mit Mitgefühl und innerer Offenheit verbinden.","I want to combine strength with compassion and inner openness.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Der Wandel ist für mich eine Erfahrung im Körper und Nervensystem, nicht im Intellekt.","For me the change is an experience in body and nervous system, not in the intellect.",3],["Erst wenn ich spüre, dass ich loslassen kann, ohne zu fallen, beginnt meine Wandlung.","Only when I feel I can let go without falling does my change begin.",3],["Ich wünsche mir Begegnung ohne Machtkampf und ohne Tricks.","I want encounter without power struggle and without tricks.",2]]}]}],"9":[{"i":"grund","d":"Grundthema","e":"Core theme","u":[{"i":"leid","d":"Leidenschaft und Grundmuster","e":"Passion and basic pattern","x":[["Ich fühle mich seelisch träge, nicht körperlich.","I feel sluggish in my soul, not in my body.",3],["Ich habe den Zugang zu meinem eigenen Impuls verloren.","I have lost touch with my own impulse.",3],["Ich vergesse, was sich in mir bewegt.","I forget what is moving inside me.",3],["Ich vergesse mich selbst.","I forget myself.",3],["Mein Frieden ist oft ein Kompromiss.","My peace is often a compromise.",3],["Meine Ruhe schützt mich eher, als dass sie Frieden ist.","My calm protects me more than it is peace.",3],["Ich weiche meinem eigenen Sein unbewusst aus.","I unconsciously avoid my own being.",3],["Ich fühle mich innerlich starr.","I feel rigid inside.",2],["Ich bin oft nicht richtig präsent.","I am often not fully present.",2],["Ich muss mich in Routinen nicht entscheiden.","In routines I don't have to decide.",2]]},{"i":"leit","d":"Leitgedanke und Prinzip","e":"Guiding thought and principle","x":[["Ich möchte lebendig sein statt mich zu fügen.","I want to be alive instead of resigning myself.",3],["Für mich ist Frieden, selbst anwesend zu sein, nicht, dass es keinen Konflikt gibt.","For me peace means being present as myself, not the absence of conflict.",3],["Mir ist Einheit und Verbundenheit wichtig.","Unity and connection matter to me.",2],["Ich strebe nach Harmonie, Ruhe und Frieden.","I strive for harmony, calm and peace.",3],["Ich erlebe das Leben als Fluss, nicht als festen Zustand.","I experience life as a river, not a fixed state.",2]]}]},{"i":"glaub","d":"Glaubenssätze und innere Sätze","e":"Beliefs and inner sentences","u":[{"i":"grunds","d":"Grundsätze","e":"Basic sentences","x":[["„Wenn ich ruhig bleibe, bleibt alles gut.“","“If I stay calm, everything stays fine.”",3],["„Wenn ich unauffällig bin, bleibt die Welt friedlich.“","“If I am inconspicuous, the world stays peaceful.”",3],["„Wenn mir nichts mehr wichtig ist, kann mich nichts verletzen.“","“If nothing matters to me any more, nothing can hurt me.”",3],["Ich glaube, Harmonie ist nur möglich, wenn ich selbst verschwinde.","I believe harmony is only possible if I disappear myself.",3],["Ich halte Konflikte für gefährlich.","I find conflicts dangerous.",3],["Ich glaube, Widerspruch erzeugt Ablehnung oder Chaos.","I believe contradiction creates rejection or chaos.",2],["Ich glaube, meine Impulse verändern nichts.","I feel my impulses change nothing.",3],["Ich glaube, meine Wünsche haben keine Wirkung.","I feel my wishes have no effect.",3],["Ich glaube, es macht keinen Unterschied, ob ich da bin.","I feel it makes no difference whether I am there.",3],["Wenn ich keine eigene Meinung zeige, kann ich nicht abgelehnt werden.","If I show no opinion of my own, I cannot be rejected.",2],["Wenn ich nicht störe, bin ich sicher.","If I do not disturb, I am safe.",3],["Ich will Frieden um jeden Preis, auch um den der Selbstverleugnung.","I want peace at any price, even at the price of denying myself.",2]]},{"i":"sub","d":"Sätze der Subtypen","e":"Sentences of the subtypes","x":[["Gewohnheit gibt mir Sicherheit und betäubt mich.","Habit gives me safety and numbs me.",2],["Ich gehöre dazu, indem ich mich vergesse und anpasse.","I belong by forgetting myself and adapting.",2],["Ich finde Einheit, indem ich mich selbst verliere.","I find unity by losing myself.",2],["Für mich bedeutet Nähe, mit dem anderen zu verschmelzen.","For me closeness means merging with the other.",2]]}]},{"i":"wahr","d":"Wahrnehmung und Denken","e":"Perception and thinking","u":[{"i":"aufm","d":"Aufmerksamkeit","e":"Attention","x":[["Meine Aufmerksamkeit ruht im Außen, damit ich Konflikte vermeide.","My attention rests in the outer world so that I avoid conflict.",3],["Mein Bewusstsein hat sich von meinem Zentrum entfernt.","My consciousness has moved away from my centre.",3],["Ich bleibe in Gedanken oder in Gewohnheit.","I stay in my thoughts or in habit.",2],["Ich gleite innerlich weg.","I drift away inside.",2],["Das Leben geschieht, aber ich bin nicht beteiligt.","Life happens, but I am not involved.",3],["Ich lebe an mir selbst vorbei.","I live past myself.",3],["Mein Alltag ist grau, gleichförmig und unbedeutend.","My everyday life is grey, uniform and insignificant.",2]]},{"i":"entsch","d":"Wollen und Entscheiden","e":"Wanting and deciding","x":[["Ich weiß nicht, was ich selbst will.","I don't know what I want.",3],["Ich unterscheide nicht zwischen Wollen und Müssen.","I don't distinguish between wanting and having to.",2],["Ich sage „Ja“, wo ich „Nein“ meine.","I say “yes” where I mean “no”.",3],["Ich warte, dass das Leben mich führt.","I wait for life to lead me.",3],["Es fällt mir schwer, Prioritäten zu setzen.","I find it hard to set priorities.",2],["Ich vermeide das Handeln.","I avoid acting.",3],["Mein Wille fühlt sich eingefroren an.","My will feels frozen.",3]]},{"i":"wiss","d":"Lernen und Wissen","e":"Learning and knowing","x":[["Ich lerne, indem ich zuhöre und ausgleiche.","I learn by listening and balancing.",2],["Ich bringe verschiedene Perspektiven zusammen.","I bring different perspectives together.",2],["Ich weiß unbewusst, dass alle Dinge verbunden sind.","I unconsciously know that all things are connected.",2]]}]},{"i":"gefuehl","d":"Gefühle","e":"Feelings","u":[{"i":"grundg","d":"Grundgefühl","e":"Basic feeling","x":[["Ich bin gleichgültig.","I feel indifferent.",3],["Ich fühle mich apathisch.","I feel apathetic.",3],["Ich bin still resigniert.","I am quietly resigned.",3],["Ich füge mich still in mein Schicksal, ohne zu klagen.","I quietly submit to my fate without complaining.",3],["Innen bin ich leer, nach außen sage ich „Okay“.","I feel empty inside while saying “okay” outwardly.",3],["Mein Gefühl ist erschöpft.","My feeling is exhausted.",3],["Ich bin seelisch erschöpft, ohne zu viel zu tun.","I am exhausted in my soul without doing too much.",3],["Mir fehlt chronisch seelische Energie.","I chronically lack energy in my soul.",3],["Ich habe die Freude verloren.","I have lost my joy.",3],["Unter der Apathie spüre ich noch einen feinen Rest Sehnsucht.","Beneath the apathy I still feel a faint trace of longing.",2],["Ich fühle mich innerlich getrennt.","I feel inwardly separate.",2],["Es schmerzt mich, übersehen zu werden.","It hurts me to be overlooked.",3]]},{"i":"zorn","d":"Ärger und Zorn","e":"Anger","x":[["In mir ist Zorn, der zu Konflikt führen würde.","I carry anger inside that would lead to conflict.",3],["Ich schlucke meine Wut hinunter.","I swallow my anger.",3],["Ich bin leise wütend, weil ich nicht gehört werde.","I am quietly angry that I am not heard.",2],["Ich gehe Ärger aus dem Weg.","I avoid getting angry.",3],["Ich drücke meinen Ärger passiv-aggressiv aus.","I express my anger in a passive-aggressive way.",2],["Mein Zorn kann plötzlich und unerwartet hervorbrechen.","My anger can erupt suddenly and unexpectedly.",2],["Mein Zorn zeigt sich als stille Resignation.","My anger shows up as quiet resignation.",2]]},{"i":"affekt","d":"Umgang mit Gefühlen","e":"Handling feelings","x":[["Ich lege meine Gefühle flach, statt sie zu unterdrücken.","I flatten my feelings rather than suppress them.",3],["Ich vermeide Schmerz, indem ich abwesend bin.","I avoid pain by being absent.",3],["Mein Bewusstsein löst sich von meiner inneren Bewegung.","My consciousness detaches from my inner movement.",3],["Ich betäube mich durch Gewohnheit, nicht durch Substanzen.","I numb myself through habit, not through substances.",3],["Hunger, Müdigkeit, Wünsche und Ärger spüre ich kaum.","I hardly feel hunger, tiredness, wishes or anger.",2]]}]},{"i":"verh","d":"Verhalten im Alltag und in Beziehungen","e":"Behaviour in everyday life and relationships","u":[{"i":"alltag","d":"Alltag","e":"Everyday life","x":[["Ich bin unauffällig, angepasst, zuverlässig, freundlich und umgänglich.","I am inconspicuous, adaptable, reliable, friendly and easy-going.",3],["Ich funktioniere, ohne es zu erleben.","I function without experiencing it.",3],["Ich bin pünktlich und kooperativ, aber ohne Farbe.","I am punctual and cooperative, but colourless.",3],["Ich verliere mich in Routinen.","I lose myself in routines.",3],["Ich bevorzuge bekannte, friedliche Umgebungen.","I prefer familiar, peaceful surroundings.",2],["Ich vermeide Reibung, um dazuzugehören.","I avoid friction to secure my belonging.",3],["Ich passe mich an, um Spannung zu vermeiden.","I adapt to avoid tension.",3],["Ich bin der Puffer zwischen Gegensätzen in Familie, Beruf und Beziehung.","I am the buffer between opposites in family, work and relationship.",3],["Ich bin der stille Ausgleicher und Vermittler.","I am the quiet balancer and mediator.",3],["Ich freue mich an entspannenden Aktivitäten wie Natur, Musik, Meditation und Geselligkeit.","I enjoy relaxing activities such as nature, music, meditation and being with others.",1]]},{"i":"bez","d":"Beziehung und Liebe","e":"Relationship and love","x":[["Ich zeige Liebe durch Harmonie, Akzeptanz und Verbundensein.","I show love through harmony, acceptance and connection.",2],["Ich bin liebevoll, unterstützend und oft selbstlos.","I am loving, supportive and often selfless.",2],["Ich will nicht übersehen werden.","I don't want to be overlooked.",2],["In der Gruppe gebe ich mich auf.","In a group I lose myself.",2],["Ich passe mich meinem Partner vollständig an.","I adapt completely to my partner.",2],["Ich gebe meine eigene Identität auf und gehe im Partner auf.","I give up my own identity and dissolve into my partner.",2],["Ich spiegle die Wünsche anderer.","I mirror the wishes of others.",3]]},{"i":"arbeit","d":"Beruf, Erfolg und Macht","e":"Work, success and power","x":[["Ich habe Erfolg durch Harmonie und Anpassungsfähigkeit.","I succeed through harmony and adaptability.",2],["Meine Stärken sind Gelassenheit, Unterstützung und Konfliktvermittlung.","My strengths are composure, support and conflict mediation.",2],["Meine Schwächen sind Passivität und Konfliktvermeidung.","My weaknesses are passivity and conflict avoidance.",2],["Meine Macht liegt in Vermittlung, Konsens und Ausgleich.","My power lies in mediation, consensus and balance.",2],["Ich wirke durch Geduld, Diplomatie und Stabilität.","I have influence through patience, diplomacy and stability.",2],["Ich bringe verschiedene Parteien zusammen.","I bring different parties together.",2],["Ich habe ein Talent, Harmonie zu schaffen.","I have a talent for creating harmony.",3]]}]},{"i":"stress","d":"Unter Druck und im Konflikt","e":"Under pressure and in conflict","u":[{"i":"druck","d":"Reaktion auf Druck","e":"Reaction to pressure","x":[["Wenn man Druck auf mich ausübt, wächst mein Widerstand.","When pressure is put on me, my resistance grows.",3],["Bei zu vielen Forderungen ziehe ich mich zurück.","When there are too many demands, I withdraw.",3],["Wenn man mich zu schnell konfrontiert, ziehe ich mich zurück.","When I am confronted too quickly, I withdraw.",3],["Ich ziehe mich aus Gewohnheit zurück, nicht aus Angst.","I withdraw out of habit, not out of fear.",3],["Ich ziehe mich zurück, um nicht konfrontiert zu werden.","I withdraw so that I won't be confronted.",3],["Ich halte den Atem an, um die Welt ruhig zu halten.","I hold my breath to keep the world calm.",2]]}]},{"i":"abwehr","d":"Abwehr und Schatten","e":"Defence and shadow","u":[{"i":"abw","d":"Abwehrformen","e":"Forms of defence","x":[["Ich beruhige mich selbst als Lebensprinzip.","Soothing myself is my principle of life.",3],["Ich dämpfe meine Lebenskraft, um meine Umgebung stabil zu halten.","I dampen my life force to keep my surroundings stable.",3],["Ich passe mich bis zur Selbstaufgabe an.","I adapt to the point of giving myself up.",3],["Gleichgültigkeit schützt mich.","Indifference protects me.",3],["Ich weiß: Frieden ohne Handlung ist Flucht.","I know that peace without action is flight.",3],["Ich weiß: Ruhe ohne Ausdruck ist Erstarrung.","I know that calm without expression is rigidity.",3],["Mein Wissen um Einheit rutscht ins Unbewusste und wird zur Flucht aus meiner Individualität.","My knowing of unity slips into the unconscious and becomes a flight from my individuality.",2],["Mein größtes Talent und mein größtes Leiden haben dieselbe Quelle: die Abspaltung von meinem Zentrum.","My greatest talent and my greatest suffering share one source: separation from my centre.",3]]}]},{"i":"kind","d":"Kindheit und Entstehung","e":"Childhood and origin","u":[{"i":"kind1","d":"Frühe Erfahrungen","e":"Early experiences","x":[["Meine Impulse fanden keine Resonanz.","My impulses found no resonance.",3],["Meine Eltern waren überfordert, emotional distanziert oder konfliktscheu.","My parents were overwhelmed, emotionally distant or conflict-shy.",2],["Als Kind habe ich gespürt: Ich bin am sichersten, wenn ich nicht störe.","As a child I sensed: I am safest when I do not disturb.",3],["Meine natürliche Selbstbehauptung habe ich unterdrückt.","I suppressed my natural self-assertion.",3],["Ich habe protestiert, bekam keine Reaktion und gab dann auf.","I protested, got no response and then gave up.",3],["Andere sprachen lauter und schienen wichtiger.","Others spoke louder and seemed more important.",2],["Ich habe mich unsichtbar gefühlt und meinen eigenen Willen verloren.","I felt invisible and lost my own will.",3],["Ursprünglich hatte ich eine tiefe Verbundenheit mit der Welt und eine stille Freude.","Originally I had a deep connection with the world and a quiet joy.",2],["Als Kind habe ich gelernt, dass Konflikte gefährlich sind.","As a child I learned that conflicts are dangerous.",3]]}]},{"i":"koerper","d":"Körperausdruck und Haltung","e":"Body expression and posture","u":[{"i":"koer","d":"Typische Ausdrucksmuster (keine Krankheitsbilder)","e":"Typical patterns of expression (not illnesses)","x":[["Mir fehlt Spannung im Körper, meine Muskeln sind weich.","My body lacks tension and my muscles are soft.",3],["Mein Atem ist flach.","My breath is shallow.",3],["Meine Stimme ist gedämpft.","My voice is muted.",3],["Mein Körper ist da, aber nicht geladen.","My body is present but not charged.",3],["Meine Energie versickert oder läuft im Kreis.","My energy seeps away or runs in circles.",2],["Ich erlebe es im Bauchzentrum.","I experience it in my gut centre.",1],["Mein Leben verliert seinen Geschmack.","My life loses its flavour.",2]]}]},{"i":"sprache","d":"Sprache und Ausdruck","e":"Language and expression","u":[{"i":"spr","d":"Wie sie spricht","e":"How they speak","x":[["Meine Worte sind korrekt, aber ohne Farbe.","My words are correct but colourless.",3],["„Es ist okay.“ (und es ist leer)","“It’s okay.” (and it is empty)",3],["Ich spreche meinen eigenen Willen nicht aus.","I don't voice my own will.",3],["Ein einfaches „Was möchtest du?“ berührt mich tiefer als jede Analyse.","A simple “What do you want?” reaches me more deeply than any analysis.",2]]}]},{"i":"wachs","d":"Wachstum, Tugend und Übungen","e":"Growth, virtue and exercises","u":[{"i":"tugend","d":"Tugend und Entwicklung","e":"Virtue and development","x":[["Ich möchte rechtes Handeln als Tugend leben.","I want to live right action as a virtue.",3],["Ich möchte aus meiner inneren Mitte handeln, nicht aus Anpassung, Pflicht oder Ehrgeiz.","I want to act from my inner centre, not from adaptation, duty or ambition.",3],["Ich möchte mein „Ja“ und „Nein“ aus dem Herzen sprechen.","I want to speak my “yes” and “no” from the heart.",3],["Ich möchte meinen eigenen Willen finden.","I want to find my own will.",3],["Ich übe kleine Gesten: eigene Wünsche äußern, widersprechen, gestalten.","I practise small gestures: voicing my wishes, contradicting, shaping.",2],["Ich möchte Konflikt als Beziehung sehen, nicht als Bedrohung.","I want to see conflict as relationship, not as threat.",3],["Aus Selbstvergessenheit wird für mich Selbstgewahrsein.","For me, self-forgetting turns into self-awareness.",3],["Ich möchte Entscheidungen aus innerer Resonanz treffen statt aus Anpassung.","I want to make decisions from inner resonance instead of adaptation.",2],["Ich möchte Freude am Dasein statt Ehrgeiz.","I want joy in being instead of ambition.",3],["Ich möchte ruhig, geerdet, standhaft und weise sein und mir selbst lebendig gegenwärtig.","I want to be calm, grounded, steadfast and wise, and alive in my own presence.",2]]},{"i":"ueb","d":"Hinweise und Übungen","e":"Hints and exercises","x":[["Mir helfen verlässliche Strukturen, sanfte Spiegelung und unaufdringliche Wärme.","Reliable structures, gentle mirroring and unobtrusive warmth help me.",2],["Ich brauche Resonanz statt Druck.","I need resonance instead of pressure.",3],["Ich frage mich: Was möchte ich?","I ask myself: What do I want?",2],["Ich frage mich: Wo bin ich?","I ask myself: Where am I?",1],["Heute sage ich klar Ja oder Nein.","Today I say a clear yes or no.",1],["Ich atme drei ruhige Atemzüge.","I take three calm breaths.",1],["Ich spüre beide Füße auf dem Boden und lege die Hand aufs Herz.","I feel both feet on the ground and put my hand on my heart.",1],["Ich spüre meinen Körper von innen.","I feel my body from within.",1],["Ich bemerke erste Zeichen im Körper: Seufzen, Aufrichten, Kontakt mit dem Atem.","I notice first signs in my body: sighing, straightening up, contact with my breath.",2]]}]}]},"syn":[["trägheit","traegheit","faulheit","antriebslos","antrieb","lethargie","passiv","passivität","sloth","laziness","passive","lethargy","apathie","apathy","gleichgültig","indifferen","egal","desinteresse"],["konflikt","streit","reibung","auseinandersetzung","widerspruch","conflict","friction","argument","contradiction","konfrontation","confront"],["anpass","anpassung","angepasst","adapt","konform","spiegel","mirror","chamäleon","chameleon","gefallen","fügen"],["harmonie","frieden","ruhe","gelassen","ausgleich","harmony","peace","calm","composure","balance","vermittl","mediat","konsens"],["resignation","aufgeben","aufgabe","kapitulation","ergeben","fügen","giving up","capitulation","resign","submit","hoffnungslos"],["leer","leere","hohl","empty","emptiness","grau","grey","farblos","colourless","okay","taub","numb","betäub"],["wut","zorn","ärger","groll","ärgern","anger","rage","wrath","resentment","aggressiv","aggressive"],["unterdrück","schlucken","verdrängen","hinunter","suppress","swallow","repress","unterdrückt"],["selbstvergessen","selbstaufgabe","selbstverlust","verschwind","self-forget","self-abandon","loss of self","disappear","verschmelz","symbiose","fusion","merging","symbiosis","aufgehen"],["unsichtbar","übersehen","ignoriert","nicht gehört","invisible","overlooked","unheard","ignored","unbeachtet"],["entscheid","entscheidung","wollen","wille","will","decide","decision","want","wish","wunsch","wünsche","priorit"],["nein","grenze","grenzen","abgrenzen","no","boundary","boundaries","thorn","dornen","selbstachtung","self-respect"],["erschöpf","müde","müdigkeit","energiemangel","kraftlos","erschöpfung","exhaust","tired","fatigue","energy","vitalität","lebenskraft"],["körper","muskel","atem","atmung","atmen","breathing","stimme","haltung","body","muscle","breath","voice","posture","spannung","tension"],["kindheit","kind","eltern","familie","trauma","childhood","child","parents","family","früh","early"],["routine","gewohnheit","alltag","gewohn","habit","everyday","comfort","komfort","bequem"],["freude","lust","lebenslust","lebendig","joy","zest","alive","aliveness","lebendigkeit","interesse","interest","neugier","curious"],["gefühl","affekt","emotion","feeling","affect","empfind","fühlen","spüren","feel","sense"],["flucht","vermeid","ausweich","avoid","flight","escape","rückzug","withdraw","retreat","abwehr","defence","schutz","protect"],["sprache","sprechen","worte","satz","language","speak","words","sentence","sagen","say","ja sagen"],["beziehung","partner","liebe","nähe","relationship","love","closeness","verbunden","connect"],["arbeit","beruf","erfolg","macht","work","career","success","power","führung","leadership"],["handeln","tun","tat","aktiv","act","action","do","active","tugend","virtue"],["blüte","rose","wild rose","hundsrose","dog rose","hagebutte","rosehip","dornen","signatur","signature","symbol"],["gleichgewicht","mitte","zentrum","centre","center","balance","kern","core"],["dissoziation","abspaltung","getrennt","dissociation","separat","trennung","getrenntheit"]],"q":{}};
const T = {"de": {"h1": "Meinen Typ finden", "lead": "Suchen Sie ein Stichwort oder blättern Sie durch die Rubriken. Tippen Sie auf „+“, wenn ein Satz auf Sie zutrifft, und sehen Sie am Ende, welcher Typ am besten passt. Ein zusätzlicher Hinweis zur Typbestimmung, keine Diagnose.", "repPh": "Suchen: zum Beispiel Konflikt, Wut, Routine, Ja sagen", "repN": "Treffer", "repNo": "Kein Treffer. Versuchen Sie ein anderes Wort oder einen Oberbegriff.", "repW": "Wertigkeit: 1 möglich, 2 häufig, 3 typisch", "repEntries": "Einträge", "repSel": "gewählt", "repEval": "Auswerten", "repClear": "Leeren", "repRes": "Auswertung", "repResLead": "So viele gewählte Eigenschaften treffen jeden Typ (gewichtet). Das ist eine Einordnung, keine Diagnose.", "repChosen": "Ihre Auswahl", "repBack": "Zurück", "repPts": "Punkte", "typH": "Typ", "tryEx": "Zum Beispiel:", "sSuche": "Suchen", "sRub": "Rubriken", "hinw": "Eine Anregung zur Selbsterforschung, keine Diagnose und kein Ersatz für ärztliche oder therapeutische Hilfe. Für eine genaue Typbestimmung empfehlen wir zusätzlich einen der Tests oder eine persönliche Typberatung."}, "en": {"h1": "Finding my type", "lead": "Search a keyword or browse the rubrics. Tap “+” when a sentence applies to you and see at the end which type fits best. An additional hint for finding your type, not a diagnosis.", "repPh": "Search, for example conflict, anger, routine, saying yes", "repN": "matches", "repNo": "No match. Try another word or a broader term.", "repW": "Weight: 1 possible, 2 common, 3 typical", "repEntries": "entries", "repSel": "selected", "repEval": "Evaluate", "repClear": "Clear", "repRes": "Evaluation", "repResLead": "How many of your selected characteristics match each type (weighted). This is a guide, not a diagnosis.", "repChosen": "Your selection", "repBack": "Back", "repPts": "points", "typH": "Type", "tryEx": "For example:", "sSuche": "Search", "sRub": "Rubrics", "hinw": "An invitation to self-inquiry, not a diagnosis and no substitute for medical or therapeutic help. For an exact type determination we also recommend one of the tests or a personal type consultation."}};
const COL = ["#5f5f5f","#7a2fa8","#1fa688","#3cbf1f","#124fcc","#8a5222","#d4a800","#a00802","#cc6e00"];
const CSS = ".tn{max-width:680px;margin:0 auto;padding:0 1rem 7rem;color:var(--ink,#28241f)}\n.tn h1{font-family:Georgia,\"Times New Roman\",serif;margin:.2rem 0 .6rem}\n.tn .card{background:var(--paper,#fffaf0);border:1px solid var(--line,rgba(40,36,31,.14));border-radius:18px;padding:16px;margin:0 0 14px}\n.tn .card.ty{background:color-mix(in srgb,var(--ty) 9%,var(--paper,#fffaf0));border-top:5px solid var(--ty)}\n.tn .card.ty .tag,.tn .card.ty summary{color:var(--ty)}\n.tn .tag{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--bronze,#7d593d)}\n.tn .mut{color:var(--muted,#72665a);font-size:.9rem}\n.tn h2,.tn h3{font-family:Georgia,\"Times New Roman\",serif;margin:.2rem 0 .5rem}\n.tn input.rq{width:100%;font:inherit;padding:10px;border-radius:12px;border:1px solid var(--line,rgba(40,36,31,.14));background:var(--ivory,#f7f1e6);color:var(--ink,#28241f);margin:6px 0 10px;box-sizing:border-box}\n.tn button{font:inherit;cursor:pointer;border:0;border-radius:14px;padding:10px 16px;background:var(--copper,#a5603d);color:#fff}\n.tn button.alt{background:transparent;color:var(--copper,#a5603d);border:1px solid var(--copper,#a5603d)}\n.tn .seg{display:flex;gap:4px;background:color-mix(in srgb,var(--copper,#a5603d) 10%,var(--ivory,#f7f1e6));padding:4px;border-radius:14px;margin:0 0 12px}\n.tn .seg button{flex:1;min-width:0;background:transparent;color:var(--muted,#72665a);padding:9px 4px;border-radius:11px;font-size:.9rem}\n.tn .seg button[aria-pressed=\"true\"]{background:var(--paper,#fffaf0);color:var(--copper,#a5603d);font-weight:700;box-shadow:0 1px 4px rgba(0,0,0,.15)}\n.tn .chipr{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 10px}\n.tn .chipr button{padding:6px 12px;font-size:.85rem;background:transparent;color:var(--ty,var(--copper,#a5603d));border:1px solid var(--ty,var(--copper,#a5603d))}\n.tn .chipr button.on{background:var(--ty,var(--copper,#a5603d));color:#fff}\n.tn .ent{display:flex;gap:10px;align-items:flex-start;border-top:1px solid var(--line,rgba(40,36,31,.14));padding:9px 0}\n.tn .ent .tx{flex:1;font-size:.98rem}\n.tn .ent .meta{font:.78rem system-ui,sans-serif;color:var(--muted,#72665a);margin-top:2px}\n.tn .dots{color:var(--bronze,#7d593d);letter-spacing:2px}\n.tn .addb{flex:none;width:34px;height:34px;border-radius:50%;padding:0;font-size:1.2rem;background:transparent;color:var(--ty);border:1.5px solid var(--ty)}\n.tn .addb.on{background:var(--ty);color:#fff}\n.tn .selbar{position:fixed;left:12px;right:84px;bottom:calc(14px + env(safe-area-inset-bottom));max-width:600px;margin:0 auto 0 max(12px,calc(50% - 340px));background:var(--deep,#243948);color:#fff;border-radius:14px;padding:10px 14px;display:flex;align-items:center;gap:10px;box-shadow:0 6px 20px rgba(0,0,0,.25);z-index:50}\n.tn .selbar span{flex:1}.tn .selbar button{background:#fff;color:var(--deep,#243948);padding:7px 14px}\n.tn .bar{height:12px;border-radius:6px;background:var(--line,rgba(40,36,31,.14));overflow:hidden}.tn .bar i{display:block;height:100%;background:var(--ty)}\n.tn details{border-top:1px solid var(--line,rgba(40,36,31,.14));padding:10px 0}.tn summary{cursor:pointer;font-weight:700}\n.tn .hint{font-size:.82rem;color:var(--muted,#72665a);border-top:1px solid var(--line,rgba(40,36,31,.14));padding-top:12px;margin-top:20px}";

export function mount(root, lang) {
  var LANG = lang === "en" ? "en" : "de";
  var SUB = { rep: "suche" }, REPT = 9;
  var t = function () { return T[LANG] };
  var byId = function (id) { return root.querySelector("#" + id) };
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c] }) };
  var sty = function (n) { return 'style="--ty:' + COL[n - 1] + '"' };
  var seg = function (key, items) { return '<div class="seg" role="tablist">' + items.map(function (a) { return '<button type="button" data-tn-seg="' + key + ':' + a[0] + '" aria-pressed="' + (SUB[key] === a[0]) + '">' + esc(a[1]) + '</button>' }).join("") + '</div>' };
  let REPQ = "", SEL = new Set(), REPRES = false;
  const nrm = s => String(s).toLowerCase().replace(/ä/g, "a").replace(/ö/g, "o").replace(/ü/g, "u").replace(/ß/g, "ss").replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();
  const lev1 = (a, b) => { if (Math.abs(a.length - b.length) > 1) return false; let i = 0, j = 0, e = 0; while (i < a.length && j < b.length) { if (a[i] === b[j]) { i++; j++ } else { if (++e > 1) return false; if (a.length > b.length) i++; else if (b.length > a.length) j++; else { i++; j++ } } } return e + (a.length - i) + (b.length - j) <= 1 };
  let SYNN = null;
  function synGroups() { return SYNN || (SYNN = REP.syn.map(g => g.map(nrm))) }
  function expand(tok) { const out = new Set([tok]); synGroups().forEach(g => { if (g.some(w => (w.length >= 4 && tok.length >= 4 && (w.startsWith(tok) || tok.startsWith(w))) || w === tok)) g.forEach(w => out.add(w)) }); return [...out] }
  function wordHit(words, tok) { return words.some(w => w.includes(tok) || (tok.length >= 5 && lev1(w.slice(0, tok.length), tok))) }
  let IDX = null;
  function repIndex() {
    if (IDX && IDX.l === LANG) return IDX.a;
    const a = [];
    Object.keys(REP.typ).forEach(n => REP.typ[n].forEach((r, ri) => r.u.forEach((u, ui) => u.x.forEach((x, xi) => {
      const txt = LANG === "en" ? x[1] : x[0], ctx = (LANG === "en" ? r.e + " " + u.e : r.d + " " + u.d);
      a.push({ id: n + "." + ri + "." + ui + "." + xi, typ: +n, r, u, x, txt, norm: nrm(txt), words: nrm(txt + " " + ctx).split(" "), w: x[2], q: x[3] });
    }))));
    IDX = { l: LANG, a }; return a;
  }
  function repSearch(q) {
    const toks = nrm(q).split(" ").filter(w => w.length >= 2); if (!toks.length) return [];
    const exp = toks.map(expand);
    const run = useSyn => repIndex().map(e => { let s = 0; for (let i = 0; i < toks.length; i++) { const direct = wordHit(e.words, toks[i]), viaSyn = useSyn && !direct && exp[i].some(w => wordHit(e.words, w)); if (!direct && !viaSyn) return null; s += direct ? 3 : 1 } return { e, s: s + e.w } }).filter(Boolean).sort((a, b) => b.s - a.s).map(o => o.e);
    const d = run(false); return d.length >= 8 ? d : run(true);
  }
  const dots = w => `<span class="dots" title="${esc(t().repW)}">${"●".repeat(w)}${"○".repeat(3 - w)}</span>`;
  function entHtml(e) {
    const on = SEL.has(e.id), qq = (REP.q[e.typ] || {})[e.q], q = qq ? qq[LANG === "en" ? 1 : 0] : e.q, rn = LANG === "en" ? e.r.e + " › " + e.u.e : e.r.d + " › " + e.u.d;
    return `<div class="ent" ${sty(e.typ)}><button type="button" class="addb ${on ? "on" : ""}" data-tn-sel="${e.id}" aria-label="+">${on ? "✓" : "+"}</button><div class="tx">${esc(e.txt)}<div class="meta">${esc(t().typH)} ${e.typ} · ${esc(rn)} · ${dots(e.w)}</div></div></div>`;
  }
  function repBody() {
    if (REPRES) return repResult();
    const all = repIndex();
    if (SUB.rep === "suche") {
      if (REPQ.trim()) { const r = repSearch(REPQ); return `<p class="mut">${r.length} ${esc(t().repN)}</p>` + (r.length ? r.slice(0, 80).map(entHtml).join("") : `<p>${esc(t().repNo)}</p>`) }
      const ex = LANG === "en" ? ["conflict", "anger", "routine", "fear", "control", "love"] : ["Konflikt", "Wut", "Routine", "Angst", "Kontrolle", "Liebe"];
      return `<p class="mut">${esc(t().tryEx)}</p><div class="chipr">${ex.map(w => `<button type="button" class="alt" data-tn-q="${w}">${esc(w)}</button>`).join("")}</div>`;
    }
    const L = LANG === "en", n = String(REPT), b = {};
    const chips = `<div class="chipr">${Object.keys(REP.typ).map(k => `<button type="button" ${sty(+k)} class="${k === n ? "on" : ""}" data-tn-rt="${k}">${k}</button>`).join("")}</div>`;
    return chips + `<div class="card ty" ${sty(+n)}><div class="tag">${esc(t().typH)} ${n}</div><p class="mut">${all.filter(e => e.typ == n).length} ${esc(t().repEntries)}</p>` + REP.typ[n].map((r, ri) => `<details><summary>${esc(L ? r.e : r.d)} <span class="mut">(${r.u.reduce((s, u) => s + u.x.length, 0)})</span></summary>` + r.u.map((u, ui) => `<h4 style="margin:10px 0 0;color:var(--mut)">${esc(L ? u.e : u.d)}</h4>` + u.x.map((x, xi) => entHtml(all.find(e => e.id === n + "." + ri + "." + ui + "." + xi))).join("")).join("") + `</details>`).join("") + `</div>`;
  }
  function repResult() {
    const all = repIndex(), sel = all.filter(e => SEL.has(e.id)), sc = {}, mx = {};
    all.forEach(e => { mx[e.typ] = (mx[e.typ] || 0) + e.w });
    sel.forEach(e => { sc[e.typ] = (sc[e.typ] || 0) + e.w });
    const top = Math.max(1, ...Object.values(sc));
    const rows = Object.keys(REP.typ).map(k => { const p = sc[k] || 0; return `<div style="margin:10px 0;--ty:${COL[k - 1]}"><div style="display:flex;justify-content:space-between"><b style="color:var(--ty)">${esc(t().typH)} ${k}</b><span class="mut">${p} ${esc(t().repPts)}</span></div><div class="bar"><i style="width:${Math.round(100 * p / top)}%"></i></div></div>` }).join("");
    return `<h3>${esc(t().repRes)}</h3><p class="mut">${esc(t().repResLead)}</p>${rows}<h4>${esc(t().repChosen)} (${sel.length})</h4>${sel.map(entHtml).join("")}<p><button type="button" class="alt" data-tn-rr="0">${esc(t().repBack)}</button></p>`;
  }
  function repRefresh() { const b = byId("repbody"); if (b) b.innerHTML = repBody(); const s = byId("selbar"); if (s) s.outerHTML = selBar(); else if (SEL.size) root.insertAdjacentHTML("beforeend", selBar()) }
  function selBar() { return SEL.size && !REPRES ? `<div class="selbar" id="selbar"><span>${SEL.size} ${esc(t().repSel)}</span><button type="button" data-tn-re="1">${esc(t().repEval)}</button><button type="button" data-tn-rc="1">${esc(t().repClear)}</button></div>` : `<span id="selbar" hidden></span>` }
  function render() {
    root.innerHTML = '<div class="tn"><style>' + CSS + '</style><h1>' + esc(t().h1) + '</h1>' + (REPRES ? "" : seg("rep", [["suche", t().sSuche], ["rub", t().sRub]])) +
      (SUB.rep === "suche" && !REPRES ? '<div class="card"><p class="mut" style="margin-top:0">' + esc(t().lead) + '</p><input id="tn-rq" class="rq" type="search" placeholder="' + esc(t().repPh) + '" value="' + esc(REPQ) + '" autocomplete="off"></div>' : '') +
      '<div id="repbody">' + repBody() + '</div><p class="hint">' + esc(t().hinw) + '</p>' + (SEL.size && !REPRES ? selBar() : '<span id="selbar" hidden></span>') + '</div>';
  }
  root.addEventListener("click", function (e) {
    var el = e.target.closest("button"); if (!el || !root.contains(el)) return; var d = el.dataset;
    if (d.tnSel) { SEL.has(d.tnSel) ? SEL["delete"](d.tnSel) : SEL.add(d.tnSel); if (REPRES) { repRefresh(); return } el.classList.toggle("on"); el.textContent = SEL.has(d.tnSel) ? "\u2713" : "+"; var s = byId("selbar"); if (s) s.outerHTML = selBar(); return }
    if (d.tnRe) { REPRES = true; render(); window.scrollTo(0, 0); return }
    if (d.tnRr !== undefined) { REPRES = false; render(); return }
    if (d.tnRc) { SEL.clear(); REPRES = false; render(); return }
    if (d.tnSeg) { var p = d.tnSeg.split(":"); SUB[p[0]] = p[1]; return render() }
    if (d.tnQ) { REPQ = d.tnQ; return render() }
    if (d.tnRt) { REPT = +d.tnRt; return render() }
  });
  root.addEventListener("input", function (e) { if (e.target.id === "tn-rq") { REPQ = e.target.value; repRefresh() } });
  render();
}
